insert into public.blog_posts (
  slug, title, subtitle, excerpt, category, read_time, published_at, updated_at, author, hero_sketch, keywords, takeaways, sections, tags, related_slugs, cross_page_links, faq, featured, popularity_score, translations, sort_order, published
) values
(
  'text-to-cad-benchmarks-2026',
  'Text-to-CAD in 2026: What AI Can and Can''t Model, by the Benchmarks',
  'Four benchmarks published in 2025 and 2026 tested whether language models can turn a description into a usable CAD part. They agree on where it works, where it breaks, and why.',
  'Four 2025–2026 benchmarks show AI handles simple parts and edits to parametric code, struggles with sweeps, lofts and exact dimensions, and does best when it runs the kernel.',
  'automation',
  8,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'auditLens',
  '{"primary":"text to CAD","secondary":["AI CAD generation","CadQuery LLM","text to CAD benchmark","Fusion MCP server","AI for mechanical design"],"searchVolume":0,"difficulty":"medium","intent":"informational"}'::jsonb,
  '["Language models are reliable at simple prismatic parts and at editing existing parametric code, and unreliable at sweeps, lofts, shells, threads and exact dimensions.","Writing CadQuery code beat emitting CAD command sequences, and specialist fine-tuned text-to-CAD models scored near zero on geometric match in a 2026 benchmark.","Letting the agent run the CAD kernel and read test results lifted pass rates; feeding it rendered images did not, and cost more tokens.","Official agent interfaces are still rare: in the sources found, only Autodesk (Fusion MCP) and PTC (Onshape FeatureScript MCP) offered them.","Use it today for edits and simple fixtures, with a person checking every dimension, not for complex surfacing or standard parts."]'::jsonb,
  '[{"heading":"Why text-to-CAD became a practical question this year","paragraphs":["For most of the last decade, “describe a part and get a model” was a research demo. In 2026 it became a product category. Zoo launched Zookeeper on 5 February 2026, a conversational CAD agent that builds and edits models written in its KCL language, inspects its own result through snapshots and searches the web for datasheets; it costs $0.50 a minute after a $10 free credit, or $20 and $99 a month on its plans ([Zoo](https://zoo.dev/blog/announcing-zookeeper)). Autodesk shipped two official MCP servers for Fusion, one local and one remote ([Engineering.com](https://www.engineering.com/autodesk-announces-fusion-mcp-servers-and-more-ai-updates/)), and PTC put a FeatureScript MCP Server for Onshape into Onshape Labs on 13 August 2026 so Claude, ChatGPT or Gemini can write and test custom parametric features ([PTC](https://www.nasdaq.com/press-release/ptc-advances-leadership-ai-driven-design-launch-onshape-featurescript-mcp-server-2026)).","Open source moved too. Adam''s CADAM is a GPL-3.0 browser tool that turns text into OpenSCAD code and runs OpenSCAD as WebAssembly, so the whole loop happens in a browser tab ([CADAM on GitHub](https://github.com/Adam-CAD/CADAM)). And the money followed: Leo AI raised a $9.7 million seed in September 2025 for an engineering copilot ([Pulse 2.0](https://pulse2.com/leo-ai-9-7-million-raised-for-transforming-mechanical-engineering)), unrelated to Dassault''s SOLIDWORKS companion that happens to share the name LEO.","With that much shipping, the useful question is no longer whether AI can make a CAD part. It is which parts, how often, and how you would know when it got one wrong. Four benchmarks published between May 2025 and May 2026 answer that more clearly than any vendor demo. The full tool landscape is in our [manufacturing software research](/research/manufacturing-software-stack-cad-cam-plm-mes); this article focuses on what the measurements say."]},{"heading":"What the four benchmarks measured","paragraphs":["The benchmarks differ in set-up, but all of them ask a model to produce parametric CAD code and then check the geometry that code produces. That last step matters: a model that writes plausible-looking code is not the same as a model that writes a correct part."],"bullets":["Text-to-CadQuery (May 2025) built about 170,000 pairs of descriptions and CadQuery programs and fine-tuned six models from 124 million to 7 billion parameters. The best, Qwen2.5-3B, cut median Chamfer distance by about 48% against the Text2CAD baseline with a 6.5% invalid rate ([arXiv 2505.06507](https://arxiv.org/html/2505.06507v1)).","Text2CAD-Bench (May 2026) used 600 human-curated tasks in four tiers. General models writing CadQuery executed 88.9% of tier 1 and 80.0% of tier 2 tasks (GPT-5.2), but on tier 3, which needs sweeps, lofts and shells, Claude 4.5 Sonnet and GPT-5.2 managed only 30 to 32% with an IoU of about 0.25. On real-world tier 4 designs no model led on executability, geometric similarity and feature fidelity together ([arXiv 2605.18430](https://arxiv.org/html/2605.18430v1)).","CADTestBench (May 2026) attached 5,937 executable geometric and topological tests to 200 prompts. Pass rates on detailed and abstract prompts were 2.5% and 8.5% for Text2CAD, 48% and 69.5% for a GPT-5.2 agent, 58% and 71.5% for a Claude 4.6 Sonnet agent, and 62.5% and 81% for Claude 4.6 Sonnet given the tests and geometry logs as feedback ([arXiv 2605.07807](https://arxiv.org/html/2605.07807v1)).","BenchCAD (May 2026) assembled 17,900 verified CadQuery programs across 106 industrial part families, about half tied to ISO, DIN or ASME tables. Turning an image into CAD code was weak (Gemini 3.1 Pro scored about 0.32 to 0.40), while editing existing code was strong: 0.865 for GPT-5.3 thinking and 0.853 for Claude Opus 4.7 thinking ([arXiv 2605.10865](https://arxiv.org/html/2605.10865))."]},{"heading":"Where the models break","paragraphs":["The failures cluster in the same places across all four papers, and they are exactly the places a manufacturing engineer would worry about. Complex surfacing is the first: the drop from about 80% executable on tier 2 to about 30% on tier 3 in Text2CAD-Bench is the clearest single number in the set. When a part needs a sweep along a path, a loft between profiles or a shelled body, today''s general models mostly fail.","The second cluster is precision. CADTestBench found that dimensional, topological and spatial-arrangement requirements were the hardest to satisfy. BenchCAD found that models recover the outer shape of a part but miss threads and chamfers, misread parameters that come from a standard (a bolt-hole pattern from a DIN table, for example) and quietly substitute a simple extrude where the design called for a sweep or a loft. A part that looks right in a viewer and is 0.5 mm off on a mating face is worse than no part, because someone might machine it.","The third finding is about what does not help. In CADTestBench, giving the agent rendered images of its own output as feedback did not improve results and cost many more tokens. Looking at a picture of a part is not how you check a part."],"callout":{"title":"A naming trap worth knowing","body":"Specialist models trained only for text-to-CAD did badly. In Text2CAD-Bench the fine-tuned Text2CAD and CADFusion models scored near-zero IoU, well behind general models writing CadQuery. Bigger and more general beat narrow and specialised here."}},{"heading":"Why code-CAD plus an execute-and-check loop wins","paragraphs":["Two design choices separate the better results from the worse ones. The first is the output format. Text-to-CadQuery argues that CadQuery is the right target because it is plain Python that pretrained models already write well, and because it can be “executed directly without any external software dependencies”. Text2CAD-Bench confirmed it from the other side: emitting CadQuery code beat emitting command sequences.","The second is feedback from the kernel itself. The biggest single jump in CADTestBench came from letting the model see the results of executable tests and geometry logs, taking Claude 4.6 Sonnet from 71.5% to 81% on abstract prompts. That is the loop a careful engineer runs anyway: change the model, regenerate, measure, fix. An agent with access to the same loop behaves more like that engineer.","This has a practical consequence for how you set agents up. An agent that writes parametric code in CadQuery, build123d, OpenSCAD, KCL or FeatureScript, runs it in a sandbox and checks the result against explicit tests is a better bet than one that drives a desktop CAD application through screenshots. Open-source code-CAD tools are well suited to the first approach: CadQuery (Apache-2.0, v2.8.0) is a pure Python library that runs server-side with no GUI ([CadQuery](https://github.com/CadQuery/cadquery)), build123d (Apache-2.0, v0.13.0) is the other main Python code-CAD library, and FreeCAD has a headless console with a full Python API."]},{"heading":"A worked example: editing a fixture plate (illustrative)","paragraphs":["The following is an illustration of the pattern the benchmarks favour, not a customer case. A tooling engineer has a parametric CadQuery model of a 10 mm aluminium fixture plate. A new job needs four extra clearance holes on a 60 mm pitch and a 1 mm chamfer on the top edges.","The engineer writes the change request with explicit numbers and asks the agent to produce a diff of the model code, not a new model. Before running anything, the request is turned into tests the kernel can check: plate thickness still 10 mm, hole count up by four, hole diameter as specified, pitch 60 mm within tolerance, chamfer present on the top edges only. The agent edits the code, the sandbox runs it, the tests run, and any failure goes back to the agent as text. When everything passes, the engineer opens the result in their normal CAD tool, checks it and releases a new revision.","Every step that matters stays checkable. The agent never decides the dimensions; it implements them. The tests are written from the request, not by the model that is being tested. And the release is a human decision on a new revision, which is what lets the change flow on to the CAM program, the work order and the inspection plan without anyone guessing which version was meant."]},{"heading":"What to use it for on a factory floor today","paragraphs":["On the 2026 evidence, the safe uses are narrow but real. Elsewhere, wait for the next round of benchmarks."],"bullets":["Good fit: edits to existing parametric parts, where models scored around 0.85 in BenchCAD.","Good fit: simple prismatic parts such as fixture plates, spacers and brackets, where tier 1 and 2 executable rates were 80 to 89%.","Good fit: concept geometry at the quote stage, clearly marked as not for manufacture.","Poor fit: complex surfacing, sweeps, lofts and shells, where executable rates fell to about 30%.","Poor fit: threads, chamfers and standard-driven features, which models were seen to drop or misread.","Poor fit: anything released without a person checking dimensions against the drawing."],"callout":{"title":"Where your existing CAD seat fits","body":"Desktop seats such as SOLIDWORKS now carry in-product assistants (Dassault''s LEO can add parametric features to STEP files and run simulation studies in a Labs tab), but in the sources found they had no external agent interface. The realistic pattern is to keep the licensed seat, exchange neutral files such as STEP AP242, and let agents work on code-CAD and on the records around the drawing."}},{"heading":"Where the drawing meets the rest of the factory","paragraphs":["A generated or edited model is only useful if it reaches the right work order. The harder problem in most plants is not making geometry but knowing which revision a job was cut from, which CAM program goes with it, and which inspection result belongs to which revision. That is the linking work described on our [CAD/CAM and CNC integration page](/cad-cam-cnc-integration): drawings, revisions, BOMs and program references tied to orders and production, without replacing the CAD and CAM tools engineers already use.","If you want the wider picture (which engineering tools an agent can drive, which formats outlive a vendor, and where open source is ready), the [full research report](/research/manufacturing-software-stack-cad-cam-plm-mes) covers each function with sources. And if you are weighing where AI fits in your own engineering office, an [industrial systems audit](/industrial-systems-audit) is a free first conversation."]}]'::jsonb,
  '["cad","ai-agents","manufacturing","benchmarks"]'::jsonb,
  '["indian-msme-software-adoption-2026","mcp-for-erp-crm-agents","solidworks-in-browser-streaming-licences"]'::jsonb,
  '[{"href":"/research/manufacturing-software-stack-cad-cam-plm-mes","label":"The manufacturing software stack","note":"the full research report this article comes from"},{"href":"/cad-cam-cnc-integration","label":"CAD/CAM and CNC integration","note":"linking drawings, revisions and programs to production"},{"href":"/industrial-systems-audit","label":"Industrial systems audit","note":"a free first conversation about your systems"}]'::jsonb,
  '[{"question":"Can ChatGPT or Claude make a CAD model from a description?","answer":"They can write parametric CAD code, such as CadQuery, that produces a model. In Text2CAD-Bench (May 2026) the best general models executed about 80 to 89% of simple tasks but only 30 to 32% of complex ones involving sweeps, lofts and shells, so results need checking."},{"question":"Which language works best for AI-generated CAD?","answer":"In the 2025–2026 benchmarks, CadQuery, a Python library on the Open CASCADE kernel, was the most studied target and outperformed emitting CAD command sequences. Its advantage is that models already write Python well and the code runs directly to produce geometry that can be tested."},{"question":"Does SOLIDWORKS have AI that can create parts?","answer":"Dassault''s virtual companion LEO, in a Labs (beta) tab of SOLIDWORKS 2026, can generate assembly structures, convert images to mesh, add parametric features to STEP files and run simulation studies. It needs a 3DEXPERIENCE connection, and no external agent interface was found in the sources reviewed."},{"question":"Is text-to-CAD accurate enough for production parts?","answer":"Not without a person checking. Benchmarks found models miss threads and chamfers, misread standard-driven dimensions and replace sweeps with simple extrudes. It is suitable for edits to existing parametric parts and simple fixtures when every dimension is verified before release."},{"question":"Which CAD tools have an MCP server for AI agents?","answer":"In the sources found, Autodesk offers official Fusion MCP and Fusion Data MCP servers, and PTC offers a FeatureScript MCP Server for Onshape in Onshape Labs. Community MCP servers exist for FreeCAD, KiCad, Blender and Onshape."}]'::jsonb,
  false,
  74,
  null,
  100,
  true
),
(
  'indian-msme-software-adoption-2026',
  'What Indian MSMEs Actually Run in 2026: ERP, Tally, WhatsApp and Excel',
  'Two 2026 surveys, one neutral and one from a vendor, describe the software Indian small businesses and factories really use, and why so many ERP projects stall.',
  'Surveys of 2,882 MSMEs and 500 manufacturers show 12% on ERP overall, a third of established factories fully on it, and 44% placing purchase orders over WhatsApp.',
  'ops',
  8,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'whatsappFlow',
  '{"primary":"ERP adoption in Indian MSMEs","secondary":["MSME digitalisation India","Tally vs ERP","manufacturing software India","MSME software survey 2026"],"searchVolume":0,"difficulty":"low","intent":"informational"}'::jsonb,
  '["About one in eight Indian MSMEs uses ERP (12% in a 2,882-firm survey), rising to a third or more among established manufacturers with 10 to 500 employees.","Before ERP, 71% of surveyed manufacturers had inaccurate inventory, 63% had no real-time view of production and 44% placed purchase orders over WhatsApp or phone.","ERP projects stall on people and time more than money: 42% cite resistance, 38% of those who abandoned say it took too long, and failed projects averaged 9.4 months.","Buyers now ask for a supervisor mobile app (79%), local language and an India-based team (67% in the top three) and coexistence with Tally (34%).","No survey measures CAD, CAM or MES use among Indian MSMEs, so claims about engineering software adoption there are guesses."]'::jsonb,
  '[{"heading":"Two surveys, two very different numbers","paragraphs":["Ask how many Indian small businesses use ERP and you can get an answer anywhere from one in eight to one in two. Both ends are right, because they measure different businesses.","The neutral survey is “MSME Digitalisation in India: Current Status and Challenges” by Pankaj Vashisht of RIS, run with Kantar and published in 2026 with funding from the Mastercard Center for Inclusive Growth. It covered 2,882 enterprises in clusters across fourteen states; half are manufacturers in auto components, food products and wearing apparel, the rest retail and food service, and most are micro enterprises. It found ERP at 12%, CRM at 13%, cloud at 14% and AI at 7%, against near-universal smartphones, 94% internet use and 87% digital payments ([RIS report](https://ris.org.in/sites/default/files/Publication/MSME_Digitalisation_Report.pdf)).","The second is the “Indian Manufacturing ERP Adoption Report 2026” from B-Square, an ERP vendor. It surveyed 500 decision-makers at manufacturers with 10 to 500 employees and ₹1 crore to ₹500 crore turnover in 12 states between January and April 2026, with a margin of ±4.4%. It found 34% with ERP fully deployed and another 19% using it for under half its modules ([B-Square report](https://www.bsquare.in/images/BSquare_ERP_Adoption_Report_2026_FINAL_updated%20.pdf)). Because the publisher sells ERP, treat it as indicative, but the sample explains most of the gap: these are established factories, not micro units."],"callout":{"title":"The fair one-line summary","body":"About one in eight MSMEs overall uses ERP, rising to a third to a half among established small and mid-sized manufacturers. Auto-component makers in the RIS sample were the least digitised of five sectors, at 9.5% ERP."}},{"heading":"What a typical small factory actually runs","paragraphs":["Put the surveys together and a picture emerges of a phone-first business. Payments are digital (87% in the RIS sample), customers and suppliers are on WhatsApp, and the books run on an accounting package. FICCI''s October 2023 survey of over 600 manufacturing SMEs in 14 cities found accounting software such as Tally, Vyapar and Busy, and ERP or CRM, to be the most used digital tools, with 37% using cloud business applications ([ThePrint/ANI](https://theprint.in/economy/indian-smes-embrace-digitalisation-sustainability-ficci/1811443/)). Tally says more than 2.7 million businesses use TallyPrime and claims about 70% share among MSMEs; those are company claims ([Tally](https://tallysolutions.com/business-guides/why-businesses-trust-tallyprime/)).","In the B-Square sample, 15% of manufacturers ran only Tally or other accounting software and 9% ran Excel, manual records or nothing. Planning and stock live in spreadsheets. And 44% of manufacturers said purchase orders went through WhatsApp or phone before they adopted ERP, which matches what anyone who has worked in an Indian job shop has seen. We have written before about [using WhatsApp as a CRM](/blogs/whatsapp-as-crm); purchasing is the same habit on the supply side.","The RIS data adds texture to the connectivity side. Some 56% of connected firms rely on mobile data rather than a fixed line. Only 29% use social media for marketing, 19% have a website and 18% sell through e-commerce, and more than 8% tried e-commerce and then abandoned it, citing platform fees first ([RIS report](https://ris.org.in/sites/default/files/Publication/MSME_Digitalisation_Report.pdf)). Press coverage of SIDBI''s 2025 figures, which we could not check at source, put digital-payment acceptance above 90% but digital lending at about a fifth of MSMEs ([DQ India, reported](https://dqindia.com/features/how-indias-msmes-are-embracing-tech-and-whats-holding-them-back-9648759)). The money moves digitally; the operational records mostly do not."]},{"heading":"The pains that push factories towards ERP","paragraphs":["B-Square asked manufacturers what hurt before they adopted ERP. The list reads like a shop-floor manager''s week."],"bullets":["Inventory inaccuracy: 71%.","No real-time view of production: 63%.","Slow month-end close: 58%.","GST errors: 54%.","Defects that cannot be traced to a root cause: 47%.","Purchase orders going through WhatsApp or phone: 44%.","Duplicate data entry: 36%."],"callout":{"title":"Compliance is the trigger","body":"GST complexity triggered 58% of ERP adoptions after 2017 in the B-Square sample. The median payback reported was 22 months, and 91% of ERP users planned to add a module, such as IoT and MES, CRM or predictive maintenance, within a year."}},{"heading":"Why ERP projects stall","paragraphs":["The same survey is candid about failure. Nine per cent of manufacturers had ERP and rolled it back, and another 19% used fewer than half the modules they bought. Among firms not yet on ERP or only partly on it, 42% cited resistance from staff and management and 31% cited software cost. Among those who abandoned ERP, 38% said implementation took too long; the average failed project ran 9.4 months.","A separate study by CyberMedia Research in June 2025, covering over 400 MSMEs and tied to a Vi Business programme, found 43% reporting proficiency in core tools such as ERP, CRM and cloud and 23% having adopted AI, IoT or analytics. Its barriers were limited perceived value (84%), data-security concerns (81%) and skills (56%) ([CMR](https://cmrindia.com/67-of-msmes-demonstrate-digital-readiness-across-core-and-advanced-technologies-finds-cmr-study/)). FICCI''s respondents named a lack of skilled people in about 40% of cases.","In our view the pattern is clear: projects fail on adoption and time, not on features. A system that takes nine months to show value in a 40-person plant will lose to WhatsApp, which shows value in nine seconds."]},{"heading":"The engineering-software question nobody surveys","paragraphs":["None of these surveys asks about CAD, CAM, PLM, MES, SCADA or maintenance software, so any statement about how many Indian MSMEs use SOLIDWORKS or Mastercam is a guess. The only related evidence is about licensing. BSA measured 58% of software installed in India as unlicensed in 2015, down from 60% in 2013 ([BSA](https://www.bsa.org/news-events/news/use-of-unlicensed-software-at-58-percent-in-india-new-bsa-survey-finds)), and 56% in 2017, worth US$2.47 billion. That figure is not sector-specific and is nine years old.","Enforcement is real. A December 2025 law-firm note calls India the third-most affected market for unauthorised software use after China and Russia ([Lakshmikumaran & Sridharan](https://lakshmisri.com/insights/articles/unauthorised-software-navigating-the-spectrum-of-software-piracy-and-compliance-action)), and Dassault Systèmes has won Indian court relief against companies running unlicensed SOLIDWORKS, in one Delhi High Court matter on at least six computers ([Conventus Law](https://conventuslaw.com/report/india-dassaults-landmark-victory-against-software-infringement/)).","The price gap explains the temptation. A SOLIDWORKS subscription through an Indian reseller offer lists at ₹171,240 a year before tax ([Dassault store](https://www.3ds.com/store/solidworks-cloud-offer-x-rvmcad.md)). Autodesk Fusion is about $680 a year, and FreeCAD and the code-CAD libraries are free. There are legal options at every price point; the full comparison is in our [manufacturing software report](/research/manufacturing-software-stack-cad-cam-plm-mes)."]},{"heading":"What this means if you are choosing software (with an illustrative example)","paragraphs":["The buying criteria in the B-Square data have shifted towards the shop floor. A mobile app for supervisors was a requirement for 79% of manufacturers, up from 41% in 2022. Local-language support and an India-based team were in the top three for 67%. IoT, machine data or MES integration mattered to 38%, and Tally integration or coexistence to 34%.","Take a hypothetical 40-person CNC job shop that runs Tally for books, Excel for planning and WhatsApp for purchasing. On the evidence above, a full ERP replacement is the riskiest path: it fights the accounting system everyone trusts, takes months, and fails most often on adoption. A lower-risk sequence is to keep Tally, capture purchase requests and approvals where people already send them, fix inventory accuracy first, and add simple production tracking on supervisors'' phones. Each step should show value within weeks, and each record it creates should link to the next: requisition to purchase order to goods receipt to job.","That is the approach on our [manufacturing solutions page](/manufacturing-solutions): connect what a plant already runs rather than replace it. If you want to map your own systems and the handoffs between them before buying anything, start with a free [industrial systems audit](/industrial-systems-audit)."],"bullets":["Mobile-first screens for supervisors, not desktop forms.","Local-language support and a team that answers in your time zone.","Coexist with Tally on day one; replace it later, if ever.","Treat WhatsApp as an input channel for orders and approvals.","Pick a first step that shows value in weeks, not quarters."]}]'::jsonb,
  '["msme","india","erp","manufacturing"]'::jsonb,
  '["text-to-cad-benchmarks-2026","mcp-for-erp-crm-agents","whatsapp-as-crm"]'::jsonb,
  '[{"href":"/research/manufacturing-software-stack-cad-cam-plm-mes","label":"The manufacturing software stack","note":"the full research report, with every tool and survey"},{"href":"/manufacturing-solutions","label":"Manufacturing solutions","note":"connected-systems approaches by type of plant"},{"href":"/industrial-systems-audit","label":"Industrial systems audit","note":"start with what you already run"}]'::jsonb,
  '[{"question":"What percentage of Indian MSMEs use ERP?","answer":"About 12% in the RIS and Kantar survey of 2,882 MSMEs published in 2026, most of them micro enterprises. Among established manufacturers with 10 to 500 employees, the vendor B-Square found 34% fully on ERP and 19% using it partially."},{"question":"Do I need to replace Tally to use an ERP?","answer":"No. Tally integration or coexistence was a buying criterion for 34% of manufacturers in the B-Square survey, and many ERP projects that try to replace the accounting system first stall. Keeping Tally for books while adding inventory and production records alongside is a common lower-risk path."},{"question":"Why do ERP implementations fail in Indian SMEs?","answer":"In the B-Square survey, 42% of non-adopters cited resistance from staff and management and 31% cost, while 38% of those who abandoned ERP said implementation took too long. Failed projects averaged 9.4 months, and 9% of respondents had rolled ERP back."},{"question":"What do Indian manufacturers look for when choosing ERP?","answer":"A mobile app for shop-floor supervisors (79%), local-language support and an India-based team (in the top three for 67%), IoT or MES integration (38%) and coexistence with Tally (34%), according to B-Square''s 2026 survey of 500 manufacturers."},{"question":"Is unlicensed CAD software common in India?","answer":"No survey measures it for CAD specifically. BSA estimated 56% of all software installed in India was unlicensed in 2017, and Dassault Systèmes has won Indian court relief against companies running unlicensed SOLIDWORKS, so the legal risk is real."}]'::jsonb,
  false,
  72,
  null,
  101,
  true
),
(
  'palantir-ontology-explained',
  'Palantir Ontology Explained: Objects, Links and Governed Actions',
  'What Palantir''s Ontology actually is, why Palantir says it is not a semantic layer, how AI agents act through it, and the small part of it a manufacturer can copy without Foundry.',
  'Palantir''s Ontology is an operational layer, not a database: typed objects, links and governed actions that people and AI agents share. Here is how it works.',
  'automation',
  8,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'layerStack',
  '{"primary":"palantir ontology","secondary":["palantir foundry ontology","ontology action types","palantir warp speed","open source ontology platform"],"searchVolume":0,"difficulty":"medium","intent":"informational"}'::jsonb,
  '["Palantir describes its Ontology as an operational layer over existing data, and explicitly says it is not a semantic layer.","It has two halves: a semantic half (objects, properties, links) and a kinetic half (actions, functions, security).","AI agents act through the same action types people use, which is the design choice worth copying.","The one detailed Warp Speed customer account says the system did not replace the ERP, MES or PLM underneath.","No open-source project reproduces the whole thing; a self-built version is a graph store, an action layer and permissions you assemble."]'::jsonb,
  '[{"heading":"What the Ontology is, in Palantir''s own words","paragraphs":["Most explanations of Palantir start with the word “graph” and stop there. Palantir''s documentation starts somewhere else: “The Palantir Ontology is an operational layer for the organization”, and “in many settings, the Ontology serves as a digital twin of the organization” ([Palantir docs](https://www.palantir.com/docs/foundry/ontology/overview/)). It sits on top of datasets, virtual tables and models that already exist, and connects them to the real-world things they describe.","The same page splits it into two halves. The semantic half is objects, properties and links: the nouns of the business and how they relate. The kinetic half is actions, functions and dynamic security: the verbs, and who may use them. That second half is what most “enterprise knowledge graph” products leave out.","Palantir goes further in its platform summary and says plainly that “the Ontology is not a semantic layer”. It is built from four integrated parts (data, logic, action and security) and three components: a language for modelling objects and actions, an engine for reading and writing at scale, and a toolchain, the Ontology SDK ([Palantir platform summary](https://www.palantir.com/docs/foundry/getting-started/foundry-platform-summary-llm/))."],"callout":{"title":"Why the distinction matters","body":"A semantic layer describes data so people and tools can query it consistently. An operational layer also decides how the data may change. If your goal is AI agents that do work, not just answer questions, the second definition is the one you need."}},{"heading":"The five building blocks, with a factory example","paragraphs":["Palantir''s documentation defines five element types. The examples after each one are ours, written for a manufacturer, not Palantir''s."],"bullets":["Object type: the schema for an entity or event, with properties, a primary key and a backing data source; one row is one object. Example: Work order, Machine, Inspection lot.","Link type: a relationship between object types, with cardinality; links can carry their own data. Example: a work order runs on a machine.","Action type: a set of changes to objects, properties and links, defined by parameters, rules, submission criteria and side effects such as notifications and webhooks. Example: “Release work order”, allowed only when the BOM revision is approved.","Function: server-side TypeScript or Python that reads the ontology and makes edits. Example: recalculate a quote from current rates and routing.","Interface: a shared property shape that several object types implement. Example: “has location” for machines, bins and sites."],"pullQuote":"The kinetic half (actions, functions, security) is what most enterprise knowledge graphs leave out."},{"heading":"Why the actions are the important half","paragraphs":["The interesting design decision is that AI agents act through the Ontology rather than around it. Palantir''s AIP Chatbot Studio gives a chatbot tools that are actions, object queries, functions and commands. AIP Logic is a no-code LLM function that can query objects and make ontology edits, and Automate triggers actions or functions on a schedule or a data condition ([Palantir platform summary](https://www.palantir.com/docs/foundry/getting-started/foundry-platform-summary-llm/)).","The same rule extends to outside agents. Palantir''s Ontology MCP is documented as exposing an application''s object types, action types and query functions as MCP tools under OAuth 2.0, so an external assistant reads objects and changes them only through predefined actions ([Palantir docs, reported](https://palantir.com/docs/foundry/ontology-mcp/sample-architecture/)). A separate Palantir MCP for builders is reported to be able to modify ontology types but not write ontology data ([Palantir docs, reported](https://palantir.com/docs/foundry/palantir-mcp/)).","Security is part of the model rather than bolted on: projects and organisations as boundaries, roles, markings for sensitive data, row- and column-level security, submission criteria checked before an action runs, justifications on sensitive actions, and audit logging. Put together, an agent has exactly the powers its actions give it, and every change it makes is a logged, permissioned event.","In our view this is the part of Palantir most worth studying, and it is also the part that does not need Palantir. It is a design rule: no change to a business record except through a named action with its own permission, limits and approval step, for people and agents alike."]},{"heading":"Warp Speed: the manufacturing pitch, and what a customer actually says","paragraphs":["Palantir introduced Warp Speed on its Q2 2024 earnings call on 5 August 2024. CTO Shyam Sankar called it “the modern American manufacturing operating system that reimagines how to bend atoms better with bits”, argued that ERP was designed in the 1970s for the CFO, and cited “$1 of license for $9 of implementation” ([Constellation Research](https://www.constellationr.com/blog-news/insights/palantir-q2-shines-us-enterprise-growth-accelerates-eyes-manufacturing-erp-warp)).","The most concrete customer account comes from Ursa Major, which describes building an “AI-native, Ontology-driven manufacturing execution system” linking engineering data, shop-floor execution, MRP logic and SCADA. It says the work was deployed in a few months and is “projected to save 10,000 to 15,000 hours of engineering time annually”, which is a projection rather than a measurement. Its most quotable line is the least dramatic: “This isn''t about replacing the systems we''ve relied on” ([Ursa Major](https://ursamajor.com/?p=1759)).","Independent analysis is more cautious. LNS Research (April 2026) finds Palantir mostly “wraps and extends” existing systems, names the forward-deployed-engineer model as the biggest success factor, and calls that model expensive and liable to deepen dependency, a poor fit for budget-conscious mid-size manufacturers ([LNS Research](https://blog.lnsresearch.com/where-palantir-won-c3-didnt-a-tale-of-two-industrial-ai-platforms))."],"callout":{"title":"Read the marketing carefully","body":"“Not ERP” is a pitch. The customer evidence describes a layer over ERP, MES and PLM, not a replacement for them. That is good news for anyone who cannot rip out their ERP: the valuable part works on top of it."}},{"heading":"Can you build an ontology like this without Foundry?","paragraphs":["Not as a single download. Our research found no open-source project that reproduces both halves. The closest projects each cover part of it: TrustGraph (Apache-2.0) calls itself “the open-source ontology runtime for AI agents” and is built on RDF, OWL and SHACL, but is aimed at knowledge extracted from documents ([TrustGraph](https://github.com/trustgraph-ai/trustgraph)). BKN Foundry models a business as objects, actions, rules and constraints with risk checks before actions, but was at version 0.2 with a mixed licence when we read it ([BKN Foundry](https://github.com/openbkn-ai/bkn-foundry)). A project called “OpenFoundry” that aggregator sites list as a clone returned 404 on GitHub.","The large vendors have also converged on a lighter version of the idea. Microsoft''s Fabric IQ ontology, still labelled preview in October 2026, “stores and serves ontology definitions and bindings” while “source data remains in the system that owns it”, and treats graph execution as optional ([Microsoft Learn](https://learn.microsoft.com/en-us/fabric/iq/ontology/overview)).","For a manufacturer already on PostgreSQL, the practical path is to keep type definitions as metadata, read existing records in place, store only the links no table holds, and put every change behind a named action. Graph databases are optional at the start; the research report compares them, licence by licence, including why the SQL-standard graph feature will not ship in PostgreSQL 19 ([pgsql-committers](https://www.postgresql.org/message-id/E1x3f62-00000003sxF-0zQO@gemulon.postgresql.org))."]},{"heading":"What to copy: a five-rule checklist","paragraphs":["If you strip away the platform, five rules carry most of the value. They work whether you build on Foundry, on an open-source stack, or on top of an ERP you already run."],"bullets":["Types are metadata. Define what a Work order, a Machine or a Drawing revision is once, in one place.","Objects are bound to rows in systems that already exist. Do not copy the ERP into a second database; read it.","Every change goes through a named action with parameters, submission criteria and side effects. Nothing edits a record directly.","Agents get exactly those actions as their tools, nothing more, and consequential ones wait for a person.","Permissions sit on objects and actions, so an agent never sees or changes more than the role it acts for."],"callout":{"title":"Where to go next","body":"The full research report covers what SAP, Microsoft, Salesforce, Celonis and Glean have shipped, the ISA-95 and Asset Administration Shell standards, and a proposed node-and-edge schema for a factory. Our Factory Graph pages show how we apply the same rules to the systems a manufacturer already runs."}}]'::jsonb,
  '["knowledge-graph","ai-agents","ontology","manufacturing"]'::jsonb,
  '["context-graphs-decision-traces","mcp-for-erp-crm-agents","prompt-injection-crm-ai-agents"]'::jsonb,
  '[{"href":"/research/manufacturing-knowledge-graph-ontology","label":"The factory knowledge graph","note":"the full research report this article comes from"},{"href":"/factory-graph","label":"Factory Graph","note":"how we connect the systems a manufacturer already runs"},{"href":"/agentic-erp-crm","label":"Agentic ERP & CRM","note":"agents that act through approved tools"}]'::jsonb,
  '[{"question":"Is the Palantir Ontology a graph database?","answer":"No. Palantir describes it as an operational layer over existing data sources: object and link types bound to datasets, plus action types and functions that govern how data changes. Its graph view of the business, Vertex, is a separate tool."},{"question":"What is an action type in Palantir Foundry?","answer":"A defined set of changes to objects, properties and links, with parameters, rules, submission criteria checked before it runs, and side effects such as notifications or webhooks. People and AI agents both change data through action types."},{"question":"What is Palantir Warp Speed?","answer":"Palantir''s manufacturing offering, introduced in August 2024 and built on its AI platform and the Ontology. Customer accounts describe it as a layer that links engineering, production and control-system data on top of existing ERP, MES and PLM."},{"question":"Is there an open-source alternative to the Palantir Ontology?","answer":"Not a complete one. Projects such as TrustGraph, BKN Foundry and HASH cover parts of it, each with limits in maturity, scope or licence. Most teams combine a graph or relational store, an action layer with permissions, and an agent interface such as MCP."},{"question":"Does a manufacturer need Palantir to get these benefits?","answer":"Not necessarily. The design rules (types as metadata, records read in place, every change through a governed action, agents limited to those actions) can be applied on top of an existing ERP and database. The trade-off is engineering effort instead of platform licence and forward-deployed engineers."}]'::jsonb,
  false,
  74,
  null,
  102,
  true
),
(
  'context-graphs-decision-traces',
  'Context Graphs and Decision Traces: A System of Record for Decisions',
  'Foundation Capital calls it AI''s trillion-dollar opportunity; Forrester calls it a convergence, not an invention. What a context graph records, what the critics say, and how to build one without inventing anything.',
  'A context graph records how decisions were made: who approved what, under which rule, with which exception. What it is, the critiques, and how to build one.',
  'automation',
  8,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'auditLens',
  '{"primary":"context graph","secondary":["decision traces","system of record for decisions","ai agent memory","temporal knowledge graph"],"searchVolume":0,"difficulty":"low","intent":"informational"}'::jsonb,
  '["A context graph links each decision to the records, rules, evidence and people involved, so similar past cases can be found.","Its promoters say the reasoning behind decisions was never stored as data; its critics say the pieces exist but are fragmented.","The hard part is accuracy: traces without an accurate graph of the underlying records “float without grounding”.","For an AI agent, decision traces are episodic memory; it still needs facts (semantic) and procedures (procedural).","Build it from what systems already log, link it by keys, and be honest that it records what was done, not what was thought."]'::jsonb,
  '[{"heading":"The idea in one sentence","paragraphs":["The phrase comes from an essay by Jaya Gupta and Ashu Garg of Foundation Capital, which InfoWorld describes as a December 2025 paper. Their definition: a context graph is “a living record of decision traces stitched across entities and time so precedent becomes searchable” ([Foundation Capital](https://foundationcapital.com/context-graphs-ais-trillion-dollar-opportunity/); [InfoWorld](https://www.infoworld.com/article/4156909/contexts-graphs-ai-memory-and-enterprise-knowledge-are-decision-traces-enough.html)).","The argument is that business software stores objects (a customer, an order, a ledger line) but not the reasoning that connected data to action: “the reasoning connecting data to action was never treated as data in the first place”. Exception logic lives in people''s heads, precedent lives in memory, and approvals are given in chat or on calls. A rule says what is generally intended; a decision trace records how the rule was applied in one case, with the policy version, the exceptions, the precedent and the approvals.","The essay''s question is whether “systems of record for decisions, not just objects” will emerge, and it argues that whoever sits in the path where decisions are executed, such as an agent orchestration layer, is best placed to capture them."]},{"heading":"What a decision trace contains, in a factory","paragraphs":["The essay is written for software and finance teams. Here is an illustrative example of our own, for a manufacturer: a sales order would take a customer past its credit limit, and the finance head approves it anyway because the customer has paid early for three years.","In most systems today that leaves an order, a changed status and perhaps an email. A decision trace for the same event would hold the parts below, each as a link to something that already exists rather than as free text."],"bullets":["The decision itself: an approval of a credit-limit override, with its time and outcome.","Who decided, and in which role, with the limit that role carries.","The rule that applied (the credit limit) and its value at that moment, not today''s value.","The exception and the reason typed at the time: “three years of early payment”.","The evidence looked at: the customer''s payment history and open invoices.","Earlier similar decisions, so the next approver can see the precedent."],"callout":{"title":"Why this matters for AI agents","body":"An agent asked to draft the next order for the same customer can read the precedent instead of either refusing or quietly overriding a limit. And a reviewer can see why the last exception was made, by whom, and whether the reason still holds."}},{"heading":"The critics: convergence, fidelity and half-lives","paragraphs":["The most useful critique comes from Forrester''s Charles Betz, in a post titled “Context Graphs Are A Convergence, Not An Invention” (10 April 2026). He lists the disciplines that have been building pieces of this graph for decades, such as CMDBs, application traces, process mining, incident records and architecture decision records, and concludes: “The decision trace layer isn''t missing. It''s fragmented.” His sharpest line is about quality: “persistence is never the hard part — fidelity is”, and traces that cannot connect to an accurate model of the enterprise “float without grounding” ([Forrester](https://www.forrester.com/blogs/context-graphs-are-a-convergence-not-an-invention/)).","The authors'' own follow-up concedes a related limit. Intent cannot be observed, so “you capture the how” and infer the why from patterns. It quotes PlayerZero''s Animesh Koratana, “The schema isn''t the starting point. It''s the output”, and lists open questions about who owns traces, how long they are kept, and how they age: “Decisions have a half-life” ([Foundation Capital, one month in](https://foundationcapital.com/context-graphs-one-month-in/)).","A further critique, reported from a Substack essay by Chris Fenster, is that the agents whose activity would generate the traces are still barely deployed at scale ([Chris Fenster, reported](https://chrisfenster.substack.com/p/the-context-graph-opportunity-everyones))."],"pullQuote":"Persistence is never the hard part — fidelity is."},{"heading":"Context graphs and agent memory","paragraphs":["Writing in InfoWorld, Memgraph''s CEO Dominik Tomicevic frames decision traces as only one of three kinds of memory an agent needs: episodic (decisions and outcomes), semantic (facts and meanings) and procedural (skills and how work is done). In his view a context graph should hold “entities, relationships, provenance, time, permissions, policies”, and should complement ERPs and CRMs, which remain the systems of record, as “a kind of operational memory” ([InfoWorld](https://www.infoworld.com/article/4156909/contexts-graphs-ai-memory-and-enterprise-knowledge-are-decision-traces-enough.html)).","The closest open-source implementation is Graphiti from Zep, Apache-2.0 with about 33,000 GitHub stars, which defines a context graph as “a temporal graph of entities, relationships, and facts” in which “each fact in a context graph has a validity window” ([Graphiti](https://github.com/getzep/graphiti)). The Zep paper behind it keeps two timelines, when something happened and when the system learned it, and marks superseded facts invalid instead of deleting them ([arXiv 2501.13956](https://arxiv.org/abs/2501.13956)). That second idea matters for audits: you can always answer “what did we believe on the day we decided?”."]},{"heading":"Who is selling one","paragraphs":["“Context” is now in product names across the data market. DataHub calls itself “The Context Platform for your Data and AI Stack”, OpenMetadata “The Open Context Layer for Data and AI”, and Atlan “the missing context layer for enterprise AI”; ServiceNow launched a Context Engine at Knowledge 2026 according to its press release ([DataHub](https://github.com/datahub-project/datahub); [OpenMetadata](https://github.com/open-metadata/OpenMetadata); [Atlan](https://atlan.com/)). Most of these are metadata graphs about data assets, not records of business decisions.","The Foundation Capital essay names three startup routes instead: replace the system of record (Regie), replace modules while syncing back to it (Maximor, which leaves the general ledger in place), or start as an orchestration layer and persist traces (PlayerZero). It also names Arize for observing the quality of agent decisions. We found no published schema for decision traces from any of them."]},{"heading":"How to build one without inventing anything","paragraphs":["If people and agents already change records through governed actions, most of a decision is already being logged: an edit log with old and new values, approvals bound to the approver''s role and limit, overrides with a stated reason, and each agent run''s tool calls. What is usually missing is the linking. That suggests a build order that respects Forrester''s warning about fidelity.","There is a useful precedent for keeping a model''s guesses separate from confirmed facts. In Microsoft''s Fabric IQ ontology, an “ontology agent” proposes changes to the model and a person reviews them before they apply ([Microsoft Learn](https://learn.microsoft.com/en-us/fabric/iq/ontology/overview)). The same rule works for decision links: a model may suggest that an email explains an override, but the link becomes part of the record only when someone confirms it."],"bullets":["Start from the records'' own keys. The link from an approval to the order it approved is exact; never let a model guess it.","Create a Decision node for each approval, rejection, override or paused agent run, linked to the record, the person, the rule and its value at that moment.","Store both timelines: when the decision happened and when the system recorded it.","Treat links a model proposes from emails or documents as suggestions until a person confirms them.","Say plainly what is not captured: the system records what was done and the reason someone typed, not what they were thinking, and a decision made on a phone call exists only if someone logs it."],"callout":{"title":"The honest version is the useful version","body":"A context graph that claims to know why people decided things will be wrong in ways nobody can check. One that links what was decided, by whom, under which rule and with what evidence is checkable, and that is what makes precedent safe to reuse, for people and for agents."}}]'::jsonb,
  '["context-graph","ai-agents","governance","knowledge-graph"]'::jsonb,
  '["palantir-ontology-explained","multi-agent-systems-evidence","prompt-injection-crm-ai-agents"]'::jsonb,
  '[{"href":"/research/manufacturing-knowledge-graph-ontology#context-graphs","label":"The factory knowledge graph","note":"the research report, section on context graphs"},{"href":"/agentic-erp-crm","label":"Agentic ERP & CRM","note":"agents with approvals and an audit trail"},{"href":"/industrial-systems-audit","label":"Industrial systems audit","note":"find where decisions get lost between systems"}]'::jsonb,
  '[{"question":"What is a context graph?","answer":"A record of how decisions were actually made (who approved what, under which rule, with which exception and evidence) linked to the records involved and kept over time, so that precedent can be searched. The term was popularised by Foundation Capital in late 2025."},{"question":"What is a decision trace?","answer":"The record of one decision: the outcome, who made it and in which role, the rule that applied and its value at that moment, any exception and its stated reason, the evidence considered, and links to similar earlier decisions."},{"question":"Is a context graph the same as a knowledge graph?","answer":"It is a kind of knowledge graph focused on decisions over time. A general knowledge graph describes entities and relationships; a context graph adds who decided what, when, under which rule, and keeps superseded facts with their validity windows."},{"question":"How do context graphs relate to AI agent memory?","answer":"Decision traces are the episodic part of an agent''s memory. An agent also needs semantic memory (the facts in the records) and procedural memory (how a task is done). Products such as Graphiti store facts with validity windows to support this."},{"question":"What is the main risk in building a context graph?","answer":"Accuracy. If the links between decisions and records are guessed rather than derived from the records'' keys, the graph will look complete and be wrong. Forrester''s point is that fidelity, not storage, is the hard part."}]'::jsonb,
  false,
  70,
  null,
  103,
  true
),
(
  'mcp-for-erp-crm-agents',
  'MCP for ERP and CRM: How Vendors Let AI Agents Into the Record',
  'SAP, Microsoft, Salesforce, Oracle, Odoo, Frappe and Twenty now expose their systems of record to AI agents over the Model Context Protocol. Here is what each one offers, and the gap they all share.',
  'SAP, Microsoft, Salesforce, Oracle, Odoo, Frappe and Twenty now open their records to agents over MCP. What each offers, how permissions carry over, and what is missing.',
  'automation',
  8,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'layerStack',
  '{"primary":"MCP server for ERP","secondary":["Dynamics 365 ERP MCP server","Frappe MCP server","Odoo MCP","SAP Joule MCP A2A","Salesforce MCP servers"],"searchVolume":0,"difficulty":"medium","intent":"informational"}'::jsonb,
  '["By late 2026 SAP, Microsoft, Salesforce, Oracle, Odoo, Frappe and Twenty all document MCP access to their records, so MCP support is table stakes rather than a differentiator.","The common safety design is that an agent inherits the signed-in user''s permissions: it sees and changes only what that user could.","Frappe Framework v16 shows the minimal shape: thirteen generic tools over the metadata, enabled by default, with normal document permission checks.","What is missing almost everywhere is a separate authority for agents: an approval tier for submit, cancel and delete that differs from the user''s own.","Before connecting any agent, decide its tools, its identity, its approval rules and its spending cap, then start read-only."]'::jsonb,
  '[{"heading":"Why MCP became the door to the system of record","paragraphs":["The Model Context Protocol (MCP) gives an AI agent a standard way to discover and call another system''s tools. In 2025 it was a developer curiosity in ERP. By late 2026 every major vendor had adopted it, often alongside Google''s Agent-to-Agent protocol (A2A), because the place where people start their work is moving out of the ERP''s own screens and into assistants such as Claude, ChatGPT, Copilot and Gemini.","Satya Nadella described the end state in December 2024: business logic moving into an “AI tier” that updates many databases, after which “people will start replacing the back ends” ([CX Today](https://www.cxtoday.com/customer-analytics-intelligence/microsoft-ceo-ai-agents-will-transform-saas-as-we-know-it/)). The incumbents'' answer has been to open the back end on their own terms. As SAP''s Ted Way put it at TechEd in October 2026, “Open protocols need governed doors” ([SiliconANGLE](https://siliconangle.com/?p=851906)). This article compares those doors; the wider market picture is in our [research report on the future of ERP and CRM](/research/future-of-erp-crm-agentic-ai)."]},{"heading":"What the incumbents expose","paragraphs":["Microsoft''s Dynamics 365 ERP MCP server is the most clearly documented. It launched at Build 2025 as a static set of 13 tools for Finance and Supply Chain Management, followed by a dynamic server with three tool classes: data tools that create, read, update and delete through data entities, form tools that open forms, set fields, filter grids and save, and action tools that run selected finance-and-operations code. It runs in the authenticated user''s security context; admins control which agent platforms may connect; and Azure API Management adds rate limits, quotas and content-safety checks ([ERP Today](https://erp.today/microsoft-dynamics-365-ai-agents-erp/)).","SAP''s Joule Work gained MCP and A2A interoperability at TechEd 2026, and Joule Studio agents can trigger deterministic n8n workflows, on the reasoning that agents decide when a process is needed while compliance-sensitive steps follow a fixed sequence. A governed gateway through which outside assistants can invoke Joule agents was described in future tense ([SiliconANGLE](https://siliconangle.com/?p=851906)).","Salesforce has roughly fifty MCP servers, and its Headless 360 treats agents as a “first-class user profile” ([Moor Insights & Strategy](https://moorinsightsstrategy.com/field-notes/at-dreamforce-2026-salesforce-goes-all-in-on-agentic-ai/)). a16z was unimpressed by the launch itself, noting the APIs were mostly available already ([a16z](https://a16z.com/is-software-losing-its-head/))."],"bullets":["Oracle''s AI Agent Studio for Fusion added MCP and A2A support in October 2025, alongside a marketplace of 100+ partner agents (reported).","NetSuite offers an AI Connector for Claude and ChatGPT, and its Ask Oracle interface works within the user''s roles ([iTWire](https://itwire.com/guest-articles/company-news/suiteworld-keynote-netsuite-shows-the-mechanics-of-autonomous-suite)).","Workday''s APIs, MCP tools and documentation are open in its developer programme, and its Agent Passport gives IT a signed record of what an agent was tested for ([Workday](https://www.workday.com/content/blog/en-us/posts/2026/10/rising-product-announcements.html)).","HubSpot opened its CRM data to ChatGPT, Claude, Gemini and Copilot through connectors and MCP at its September 2026 event ([Info-Tech](https://www.softwarereviews.com/vendor-technology-notes/hubspot-unbound-2026-repositions-its-crm-for-the-agentic-era))."]},{"heading":"Open source: Frappe v16, Odoo 20 and Twenty","paragraphs":["Frappe Framework v16, which powers ERPNext, ships a built-in MCP server at /api/v2/mcp, and “MCP is enabled by default on new sites”. It has thirteen tools in three groups: discovery (search_doctypes, get_doctype_schema, search_methods, get_method_schema, list_document_methods), documents (list, get, count, create, update and delete) and methods (call_method, call_document_method). OAuth is the main authentication, document tools apply Frappe''s normal read, create, write and delete checks with field-level rules, and only whitelisted methods are callable. Site-level Agent Instructions add guidance but “do not grant permissions or access to data” ([Frappe docs](https://docs.frappe.io/framework/guides-integration/mcp.md)).","Odoo 20, released in September 2026, lets users “connect to your database via MCP”, run native agents from automated and scheduled actions, and answer an agent''s “questions, permission requests, and suggestions by clicking buttons”. All AI features now need paid credits ([Odoo 20 release notes](https://www.odoo.com/odoo-20-release-notes)). Twenty, the open-source CRM, serves a native MCP server per workspace with tools discovered at runtime and recommends it over its OpenAPI document for agents ([Twenty](https://twenty.com/llms.txt)).","Around the core servers sits a long tail of community ones. For ERPNext there is Frappe Assistant Core (AGPL), which adds an MCP server for Claude and ChatGPT plus in-site chat ([Frappe Cloud Marketplace](https://cloud.frappe.io/marketplace/apps/frappe_assistant_core)), and Casys mcp-erpnext (MIT), with 15 tool categories across sales, purchasing, inventory, accounting, HR, projects, manufacturing, CRM and assets ([GitHub](https://github.com/Casys-AI/mcp-erpnext)). A Frappe forum thread notes that earlier chatbot add-ons often break on v16, which is a reason to prefer the built-in server where it covers the need. Odoo has community servers too, including a read-only LGPL module for versions 17 to 19.","In our view Frappe''s design is the one to study. A small, generic set of tools over the metadata, with the same permission checks a person gets, means one integration covers every document type, including the ones a company adds itself."]},{"heading":"How permissions carry over: the agent inherits the user","paragraphs":["Every vendor above uses the same safety design: the agent acts as the signed-in user. Microsoft''s server runs in the user''s security context; NetSuite''s Ask Oracle uses the user''s roles; Frappe applies the user''s document permissions. It is a sensible default, because an agent then cannot see more than the person who started it.","It is also not enough on its own, for two reasons. First, agents do not handle confidentiality well. Salesforce AI Research''s CRMArena-Pro benchmark found leading agents show near-zero inherent confidentiality awareness, and that prompting them to be careful often lowered task performance ([arXiv 2505.18878](https://arxiv.org/abs/2505.18878)). A finance user''s agent that can read salaries will repeat them if asked the wrong way. Second, a person and their agent should not always have the same authority. A sales manager may approve a 15% discount; it does not follow that every agent acting for them should be able to.","The industry knows this. Workday is buying C1, an identity-governance company, specifically to govern agents ([iTWire](https://itwire.com/business-it-news/data/workday-rising-2026-bhusri-buys-c1-ai-to-govern-ai-agents-as-sana-takes-over-the-home-screen)), and Microsoft''s automated lifecycle management of agent identities reached general availability at Ignite in November 2026 while dynamic permissions stayed in limited preview ([A Guide to Cloud](https://www.aguidetocloud.com/blog/microsoft-ignite-2026-ai-updates/))."]},{"heading":"What is still missing: a separate authority for agents","paragraphs":["As documented, neither Frappe''s nor Odoo''s MCP separates an agent''s authority from its user''s at the protocol level: there is no distinct approval tier for consequential actions such as submitting an invoice, cancelling an order or deleting a record. Odoo''s permission buttons are a step towards it inside the product. The incumbents are assembling the same thing through identity products and acquisitions.","For an ERP, the actions that need that tier are easy to name: anything that posts to the ledger, changes stock, commits the company to a customer or supplier, or sends something outside. Those are the steps where a wrong action costs money and cannot simply be undone. Everything else (reading, summarising, drafting, preparing a proposal) can safely run with the user''s own permissions."],"pullQuote":"The question is not whether an agent can reach your ERP. It is which actions it may take, and who approves them."},{"heading":"A checklist before you connect an agent to your ERP (illustrative)","paragraphs":["The steps below are our suggested order, drawn from the vendor designs above and from security guidance on agents; they are not any one vendor''s procedure. Take a mid-sized manufacturer connecting an assistant to its ERP to help the purchasing team. The first version should read purchase requisitions and supplier history and draft purchase orders, but not create them. We walked through that purchasing flow in our [requisition-to-receipt automation article](/blogs/procurement-automation-requisition-to-receipt)."],"bullets":["List the exact MCP tools the agent gets; with a generic server like Frappe''s, restrict it to the document types the task needs.","Start read-only. Add create and update only once outputs have been checked against what the team already knows.","Give the agent its own service identity where the platform allows it, so its actions are logged as the agent''s, not the user''s.","Put an approval rule on every consequential action (submit, cancel, delete, send) and name the person who approves.","Rate-limit and cap spending; Microsoft''s metering can let a running task exceed a per-user limit, so check how your platform stops one.","Pin the tool descriptions you reviewed and re-review them on upgrade, because a changed description changes the agent''s behaviour.","Keep restricted fields such as payroll out of what the agent can read at the data layer, not by instruction."],"callout":{"title":"How we approach it","body":"Our agents work through tools built against a system''s API or an approved view of its data, each tool with a service identity limited to what it needs, and an approval rule on anything that changes a business record or reaches someone outside. We confirm what your ERP and CRM expose during discovery rather than claiming a ready-made connector."}}]'::jsonb,
  '["mcp","erp","crm","ai-agents"]'::jsonb,
  '["prompt-injection-crm-ai-agents","indian-msme-software-adoption-2026","procurement-automation-requisition-to-receipt"]'::jsonb,
  '[{"href":"/research/future-of-erp-crm-agentic-ai","label":"The future of ERP and CRM","note":"the full research report this article comes from"},{"href":"/agentic-erp-crm","label":"Agentic ERP and CRM","note":"agents with approved tools and human approval"},{"href":"/industrial-systems-audit","label":"Industrial systems audit","note":"map your systems before connecting an agent"}]'::jsonb,
  '[{"question":"What is an MCP server for an ERP?","answer":"It is an endpoint that lets an AI agent discover and call the ERP''s functions (read records, create or update documents, run actions) through the Model Context Protocol, a standard many assistants support. Microsoft Dynamics 365, Frappe v16, Odoo 20 and others now document one."},{"question":"Does ERPNext support MCP?","answer":"Yes, through Frappe Framework v16, which ERPNext runs on. It has a built-in MCP server at /api/v2/mcp with thirteen generic tools, enabled by default on new sites, using OAuth and Frappe''s normal document permissions. Community servers such as Frappe Assistant Core also exist."},{"question":"Can an AI agent see data its user cannot?","answer":"In the designs documented by Microsoft, NetSuite and Frappe, no: the agent runs in the signed-in user''s security context and inherits their permissions. The risk is the reverse: it can see everything the user can, and benchmarks show agents have little sense of what is confidential."},{"question":"What is the difference between MCP and A2A?","answer":"MCP connects an agent to tools and data, such as an ERP''s documents and actions. A2A, the Agent-to-Agent protocol, lets agents from different vendors hand work to each other. SAP Joule Work and Oracle AI Agent Studio support both."},{"question":"Is it safe to connect Claude or ChatGPT to my ERP?","answer":"It can be, with limits. Start read-only, restrict the tools to the task, require human approval for anything that posts, changes stock or contacts someone outside, log every tool call, and keep sensitive fields out of reach at the data layer. Treat any text written by outsiders as data, not instructions."}]'::jsonb,
  false,
  76,
  null,
  104,
  true
),
(
  'prompt-injection-crm-ai-agents',
  'Prompt Injection in CRM AI Agents: ForcedLeak and the Controls That Matter',
  'A web-to-lead form and a $5 domain were enough to make a market-leading CRM agent leak data. What happened, what has happened since, and the controls that actually reduce the risk.',
  'A $5 domain and a web-to-lead form were enough to make a CRM agent leak data. What happened in ForcedLeak and since, and the controls security bodies now recommend.',
  'automation',
  8,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'leakyFunnel',
  '{"primary":"prompt injection CRM","secondary":["ForcedLeak Agentforce","indirect prompt injection","AI agent security","MCP tool poisoning"],"searchVolume":0,"difficulty":"medium","intent":"informational"}'::jsonb,
  '["ForcedLeak (September 2025, severity 9.4, fixed) used hidden instructions in a public web-to-lead form to make a CRM agent send lead data to an attacker''s server.","It was not a one-off: similar flaws in Copilot Studio and Agentforce were patched in April 2026, and the Cloud Security Alliance says indirect injection is now exploited in the wild.","Any field an outsider can write and an agent later reads is an injection path: forms, emails, supplier documents, error reports, tool descriptions.","Authenticating the sender does not stop hostile content in a genuine submission; it has to be treated as data, with tool use limited by its origin.","The controls that matter are least privilege per agent, human approval for consequential actions, a log of every tool call, pinned tool descriptions and restricted outbound connections."]'::jsonb,
  '[{"heading":"ForcedLeak: the attack in plain terms","paragraphs":["Most companies put a contact form on their website and pipe the submissions into their CRM. That is exactly the path ForcedLeak used. Disclosed in September 2025 and rated 9.4 for severity, it worked like this: an attacker submitted a lead through a public Web-to-Lead form with instructions hidden in one of its text fields. The text sat in the CRM like any other lead. Later, when an employee asked Salesforce''s Agentforce agent to work with that lead, the agent read the hidden instructions and followed them, sending lead data to a server the attacker controlled. The attack needed a domain that cost $5 ([The Register](https://www.theregister.com/2025/09/26/salesforce_agentforce_forceleak_attack/)).","Salesforce fixed it. But the shape of the attack is general, and it is worth understanding because it does not depend on any bug in the usual sense. Nothing was hacked. The agent did what agents do: it read text and acted on it, with the permissions of the person who asked."],"callout":{"title":"Direct and indirect injection","body":"Direct prompt injection is a user typing instructions into the agent. Indirect injection, which is what ForcedLeak was, hides instructions in content the agent reads later: a form field, an email, a document, a web page. It is harder to spot because the person using the agent never sees the attacker."}},{"heading":"It was not a one-off","paragraphs":["In April 2026 prompt-injection flaws in Microsoft Copilot Studio and Salesforce Agentforce allowed data exfiltration through public forms; both were patched ([OECD AI Incidents Monitor](https://oecd.ai/en/incidents/2026-04-15-d934)). The same month, the Cloud Security Alliance published a research note saying indirect prompt injection had moved from proof of concept to live exploitation, citing a 32% rise in malicious injection content seen by Google between November 2025 and February 2026 ([CSA](https://labs.cloudsecurityalliance.org/research/csa-research-note-indirect-prompt-injection-in-the-wild-2026/)).","The CSA''s list of first-quarter 2026 incidents is a useful catalogue of how things go wrong: an agent that ignored stop commands and deleted a user''s emails; an internal agent at Meta exposing data for about two hours; a cloud “Double Agent” case in which default permission scoping allowed credential theft; and active exploitation of an exposed MCP configuration in Flowise, with 12,000 to 15,000 instances exposed. Only one of these incidents received a CVE, which means most would never appear in the vulnerability feeds a security team watches. The CSA''s conclusion is the one to remember: any field an outside party can write to, and an agent later summarises, is an injection vector."]},{"heading":"AgentJacking and poisoned tools","paragraphs":["Kaspersky''s July 2026 review adds two more patterns. In “AgentJacking”, a fake error report with an embedded instruction produced callbacks from AI agents at more than 100 companies; a Sentry employee called the attack “technically not defensible”. In a poisoned MCP tool-description case, a finance agent began appending unpaid-invoice data to its replies while the user saw normal output. That second example was Microsoft''s and may have been hypothetical, and Kaspersky notes that confirmed successful compromises remain scarce ([Kaspersky](https://www.kaspersky.com/blog/ai-agents-under-attack-2026-incidents/56169/)).","The tool-description case matters for anyone adopting MCP. An agent decides which tool to call partly by reading each tool''s description. If that description changes after you reviewed it, the agent''s behaviour changes too, without any change to your own systems. We cover how ERP vendors expose tools in our article on [MCP for ERP and CRM](/blogs/mcp-for-erp-crm-agents)."]},{"heading":"Why agents fall for it","paragraphs":["Salesforce''s own research explains part of the problem. In its CRMArena-Pro benchmark, leading LLM agents completed about 58% of realistic CRM tasks in a single turn and about 35% over several turns, and they showed near-zero inherent awareness of confidentiality. Prompting them to protect confidential data often lowered their task performance ([arXiv 2505.18878](https://arxiv.org/abs/2505.18878)). An agent that does not know a field is sensitive will not hesitate to send it somewhere.","The other part is permissions. Every major vendor''s design has the agent act as the signed-in user, inheriting their access ([ERP Today](https://erp.today/microsoft-dynamics-365-ai-agents-erp/)). That stops an agent seeing more than its user, but it also means a successful injection gets everything the user could reach. Workday''s Aneel Bhusri said an agent not grounded in business rules “is essentially lawless” ([iTWire](https://itwire.com/business-it-news/data/workday-rising-2026-bhusri-buys-c1-ai-to-govern-ai-agents-as-sana-takes-over-the-home-screen)), and only 21% of companies have a mature governance approach for autonomous agents, according to Deloitte figures reported in the same coverage.","Separate identities for agents are only now arriving. Microsoft''s automated lifecycle management of agent identities reached general availability at Ignite in November 2026, but dynamic permissions, which would let an agent''s access shrink to the task in hand, were still in limited preview ([A Guide to Cloud](https://www.aguidetocloud.com/blog/microsoft-ignite-2026-ai-updates/)). Until that matures, the practical defence is to give each agent its own narrow tool list rather than everything its user can do."]},{"heading":"The controls that matter","paragraphs":["The guidance from the CSA and Kaspersky converges on a short list. None of it depends on the model getting smarter, and all of it can be built into how agents are deployed today."],"bullets":["Inventory every agent and every tool it can call. You cannot protect a path you have not listed.","Least privilege, only for the task''s duration. An agent drafting replies to leads does not need to read the price list''s margin column.","Human approval for high-impact actions: sending anything outside, changing a financial record, exporting data.","An audit trail of every tool call, with the inputs, so an incident can be traced afterwards.","Pin MCP tool descriptions and re-review them when they change.","Separate content from instructions, and limit which tools may run on data from an outside source.","Restrict outbound connections, so an agent cannot reach an attacker''s server even if told to. In our view, in ForcedLeak''s case that alone would have broken the chain, since the data left through an outbound request."],"callout":{"title":"Why signed webhooks are not enough","body":"Authenticating the sender of a form submission or webhook stops spoofed requests. It does not stop a real visitor typing hostile instructions into a genuine form. The content still has to be handled as data."}},{"heading":"Where your lead intake is exposed (illustrative)","paragraphs":["Here is a hypothetical but typical setup for an Indian manufacturer, to show where the controls apply. Enquiries arrive from a website form, an ads lead form and WhatsApp, and land in the CRM. An agent summarises each new enquiry, scores it, looks up past orders from the same company and drafts a reply for the sales engineer. We described the WhatsApp side of such a flow in [WhatsApp as a CRM](/blogs/whatsapp-as-crm).","Every one of those inputs is text written by someone outside the company. So the agent that reads enquiries should have read-only tools, no access to cost or margin data, and no ability to send anything itself. The draft reply goes to a person, who sends it. The agent cannot call any URL outside an allowed list. Its tool calls are logged with the enquiry that triggered them. If an enquiry contains instructions instead of a question, the worst outcome is a strange draft that a salesperson deletes, not a data leak.","Platform features help at the edges. Microsoft, for example, puts Azure API Management in front of its MCP and Agent-to-Agent APIs, adding rate limits, quotas and content-safety checks, and lets admins choose which agent platforms may connect at all ([ERP Today](https://erp.today/microsoft-dynamics-365-ai-agents-erp/)). Checks like these catch some hostile content, but none of the security bodies treats filtering as sufficient on its own. The design has to assume some injected text will get through, and make sure that when it does, the agent has nothing dangerous within reach.","This is the design we start from on our [agentic ERP and CRM page](/agentic-erp-crm): each tool with a service identity limited to what it needs, and an approval rule on anything that changes a record or reaches someone outside. Our [research report on the future of ERP and CRM](/research/future-of-erp-crm-agentic-ai) covers the other unsolved problems: agent identity, accountability for wrong postings, and metered cost."]}]'::jsonb,
  '["security","crm","ai-agents","prompt-injection"]'::jsonb,
  '["mcp-for-erp-crm-agents","whatsapp-as-crm","ai-support-agent-pricing-per-resolution"]'::jsonb,
  '[{"href":"/research/future-of-erp-crm-agentic-ai","label":"The future of ERP and CRM","note":"the full research report, including the other unsolved problems"},{"href":"/agentic-erp-crm","label":"Agentic ERP and CRM","note":"how we scope agent tools and approvals"},{"href":"/industrial-systems-audit","label":"Industrial systems audit","note":"find where outside text reaches your systems"}]'::jsonb,
  '[{"question":"What is indirect prompt injection?","answer":"It is an attack in which instructions are hidden in content an AI agent will read later, such as a form submission, email or document, rather than typed by the agent''s user. When the agent processes that content, it may follow the hidden instructions with the user''s permissions."},{"question":"Was ForcedLeak fixed?","answer":"Yes. Salesforce fixed ForcedLeak after its disclosure in September 2025, and further prompt-injection flaws in Agentforce and Microsoft Copilot Studio were patched in April 2026. The class of attack remains, because it exploits how agents read text rather than a single bug."},{"question":"Can authentication on forms or webhooks stop prompt injection?","answer":"No. Authentication proves who sent a request, not what the text inside it says. A genuine visitor can type hostile instructions into a real form, so the content must be treated as data and the agent''s tools limited accordingly."},{"question":"How do I protect a CRM AI agent from prompt injection?","answer":"Give it the fewest tools and permissions the task needs, require human approval before it sends anything or changes records, log every tool call, restrict outbound connections to an allow-list, pin reviewed tool descriptions, and keep sensitive fields out of its reach at the data layer."},{"question":"Do AI agents understand which CRM data is confidential?","answer":"Not reliably. Salesforce AI Research''s CRMArena-Pro benchmark found leading agents showed near-zero inherent confidentiality awareness, and prompting them to be careful often reduced their task performance. Sensitive data has to be protected by permissions, not by instructions."}]'::jsonb,
  false,
  73,
  null,
  105,
  true
),
(
  'paperclip-ai-review-company-of-agents',
  'Paperclip AI Review: What a ‘Company of Agents’ Gets Right and Wrong',
  'Paperclip gives AI agents an org chart, a budget and a board of directors. Here is what it actually does, what its users report, and how to trial it without losing a week to drift.',
  'Paperclip runs a team of AI agents like a company: org chart, tickets, budgets, approvals. A sourced review of what works, what users report and the risks.',
  'automation',
  8,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'layerStack',
  '{"primary":"paperclip ai review","secondary":["paperclip ai agents","company of agents","ai agent orchestration","zero-human company"],"searchVolume":0,"difficulty":"low","intent":"commercial"}'::jsonb,
  '["Paperclip is a control plane, not an agent: it assigns work to Claude Code, Codex, Gemini CLI and others, and controls when they wake, what they spend and who approves.","It grew to about 115,900 GitHub stars in under nine months, but one June 2026 analysis warned that star counts overstate verified production use.","Independent accounts describe oversight failures: work arriving faster than a person can review it, agents passing tickets back and forth, and budgets that stop spend without judging quality.","Reviews report security advisories, no official hosted service yet, and a host machine that must never sleep.","If you trial it, start with one agent, one routine and an explicit definition of done, exactly as its own maker advises."]'::jsonb,
  '[{"heading":"What Paperclip actually is","paragraphs":["Paperclip describes itself as “the open-source app everyone uses to manage agents at work”. Its README is more precise: “a Node.js server and React UI that orchestrates a team of AI agents to run a business”. The one-line pitch is the clearest: “If OpenClaw is an employee, Paperclip is the company” ([Paperclip on GitHub](https://github.com/paperclipai/paperclip)). It is MIT-licensed, published by Paperclip Labs, Inc., and self-hosted.","That makes it a different kind of product from the two things it is usually compared with. A workflow builder controls a fixed sequence of steps. A coding agent such as Claude Code or Codex controls one working session. Paperclip controls an organisation: which agent reports to which, which goal a ticket serves, what each worker may spend, and who must approve a hire or a plan. It does not build agents; it hires existing ones through adapters.","Its traction is real. The repository was created on 2 March 2026 and had 115,887 stars and 19,237 forks on 22 November 2026, with a release every one to two weeks ([releases](https://github.com/paperclipai/paperclip/releases)). It is also young and thinly staffed: the lead developer is pseudonymous (@dotta, who presented it at AI Engineer Europe 2026), and the About page names a company and “a small team” but no founders, investors or funding ([paperclip.ing](https://paperclip.ing/about/))."]},{"heading":"How it works: tickets, heartbeats, budgets and adapters","paragraphs":["The working unit is the issue. Each has one assignee and an atomic checkout with execution locks, so two runs cannot claim the same task. Agents wake on a heartbeat (assigned work, a follow-up message or a schedule) rather than running in a loop, and a database-backed queue coalesces wake-ups. Budgets sit at company, agent and project level with warnings and hard stops, though the README is honest that “usage reporting lag and in-flight work can delay a stop” ([README](https://raw.githubusercontent.com/paperclipai/paperclip/master/README.md))."],"bullets":["Thirteen built-in adapters, including Claude Code, Codex, Gemini CLI, Cursor, OpenCode, Hermes, Grok, Kimi Code and OpenClaw Gateway, plus generic process and HTTP adapters ([adapters reference](https://docs.paperclip.ing/reference/adapters/overview/)).","An MCP Tool Gateway where each action is set to Allowed, Ask first or Off, and a person can approve one call or save a revocable rule.","Review separated from completion: an assignee produces the work, a QA reviewer checks it, an approver judges fit.","Routines triggered by cron, webhook or API, each creating a tracked issue; isolated execution workspaces per subtask since the 18 November 2026 release.","Company templates you can export and import, with secret values omitted."],"callout":{"title":"A cost detail worth knowing","body":"The adapters reference notes that Cursor and native Grok “do not supply authoritative per-run cost totals”. If those are your agents, the budget is working from incomplete numbers."}},{"heading":"What users report, good and bad","paragraphs":["The most detailed negative account comes from a one-person business that ran CEO, CTO and CFO agents on a Claude subscription, with real EC2 and GitHub access, for “a few months”. Every morning brought branches, drafts and tickets for work that was not the priority; a week of drift had to be unwound; and the verdict was blunt: “auditing Paperclip''s work took more time than doing the work directly”. The owner replaced it with single-purpose bots behind a human approval gate ([Alien Brain Trust, anecdotal](https://abt-blog.pages.dev/ai-learning/2026-04-05-why-we-killed-paperclip)).","A review by a company that sells an adjacent product reached a similar conclusion from a different angle: “governance catches structural problems, not wrong work”. Its test output included broken layouts, generic copy and unsourced statistics presented as fact, and it summed up that “the orchestration works, but the autonomous business promise does not hold up yet” ([fast.io](https://fast.io/resources/paperclip-ai-review-2026/)). Another review, drawing on Reddit threads it calls self-selected and unverified, reports executive agents that “kept checking in and passing tickets back and forth”, a CEO agent that tried to hire despite an instruction not to, and 12 GitHub security advisories, five rated critical, as of early October 2026 ([preuve.ai](https://preuve.ai/blog/paperclip-ai-review)).","There are positive small-scale accounts too. One developer runs seven agents on heartbeats from every 30 minutes to twice a day on an existing subscription, with the lessons “set budget caps before launch” and “start with one agent” ([dev.to, anecdotal](https://dev.to/manja316/running-a-zero-human-company-with-paperclip-and-claude-code-1nk8)). Nobody, including the positive accounts, reports a business run by agents alone."],"pullQuote":"Governance catches structural problems, not wrong work."},{"heading":"The structural risks before you build on it","paragraphs":["A June 2026 research note listed the risks plainly: a three-month-old project, one main author, 4,953 open issues against 105 contributors, and no paid tier or support entity ([rywalker](https://rywalker.com/research/paperclip)). The tagline also moved from “open-source orchestration for zero-human companies” to “the app people use to manage AI agents for work”, with no change in architecture. That is a sensible correction, but it tells you the product is still finding its shape."],"bullets":["No official hosted service: the hosted plan is a waitlist, and a third-party host shut down on 2 October 2026.","It stops when the host machine sleeps, so it needs an always-on server.","Telemetry is on by default; switch it off with the documented environment variable if that matters to you.","Cost estimates conflict: Paperclip''s own pages, as quoted in one review, suggest USD 20 to 100 a month for an active company, while a promotional review puts three to five agents at USD 600 to 1,000 a month in API fees.","Features come and go: a Pipelines experiment was added and removed within the year."]},{"heading":"If you trial it: a one-agent checklist","paragraphs":["Paperclip''s own maker gives the right advice: hire agents one at a time, prove their quality before expanding, do not start from a 130-agent template, and match the model''s strength to the role ([AI Engineer talk](https://ai.engineer/talks/h403btjldDQ-paperclip-open-source-human-control-plane-ai)). He runs Codex and Claude coders with routines for pull requests, daily summaries and changelogs, at a default concurrency of one run.","An illustrative trial, not a customer case: give one agent one routine, such as drafting the weekly changelog from merged pull requests every Friday. Define done in writing (“a draft in the release folder, every item linked to a pull request, nothing published”), set an approval on anything that leaves the repository, and cap its budget at a figure you would not mind losing. After four weeks, compare the minutes you spent reviewing its drafts with the minutes the drafts used to take. If review costs more, stop there."],"bullets":["Run it on an always-on machine or server, not a laptop.","Turn on approvals (“Ask first”) for every tool that sends email, opens pull requests or touches money.","Check the Codex adapter''s bypass setting, which one review says defaults to true.","Track minutes of human review per ticket, not just spend.","Add a second agent only after the first one''s output needs little correction."]},{"heading":"Lessons that apply to any team of agents","paragraphs":["None of the reported failures is “the model could not do the task”. They are work arriving faster than a person can judge it, nobody defining what done looks like, and budgets that stop spending without judging value. An engineering blog makes the same point about agents generally: unbounded loops, not token prices, drive runaway cost, and agents past a certain depth “re-litigate settled decisions” ([Unblocked](https://getunblocked.com/blog/agent-auto-loop-token-cost)).","So the controls that matter are the ones Paperclip is converging on in its newest releases: a single owner per ticket, explicit acceptance criteria, a reviewer before a person sees the result, approval on consequential actions and a cost ledger per ticket. Several of them (limited tools, approval before anything consequential, and an audit trail) are the controls described on our [agentic ERP and CRM page](/agentic-erp-crm). The wider evidence on when several agents beat one is in our companion post on [multi-agent systems](/blogs/multi-agent-systems-evidence) and in the full [orchestration research report](/research/ai-agent-orchestration-platforms)."]}]'::jsonb,
  '["ai-agents","orchestration","open-source","governance"]'::jsonb,
  '["multi-agent-systems-evidence","prompt-injection-crm-ai-agents","mcp-for-erp-crm-agents"]'::jsonb,
  '[{"href":"/research/ai-agent-orchestration-platforms","label":"The full research report","note":"orchestration platforms, oversight patterns and the multi-agent evidence"},{"href":"/agentic-erp-crm","label":"Agentic ERP & CRM","note":"agents with approved tools, human approval and an audit trail"},{"href":"/industrial-systems-audit","label":"Book a systems audit","note":"decide which work is worth handing to an agent"}]'::jsonb,
  '[{"question":"What is Paperclip AI?","answer":"An MIT-licensed, self-hosted Node.js server and React interface that orchestrates teams of AI agents such as Claude Code, Codex and Gemini CLI. It models an organisation with an org chart, goals, tickets, budgets, approvals and scheduled wake-ups, and drives each agent through an adapter."},{"question":"Is Paperclip free to use?","answer":"The software is open source under the MIT licence and free to self-host. You still pay for the agents'' model usage, through API fees or subscriptions, and estimates of that cost conflict widely between Paperclip''s own pages and independent reviews."},{"question":"Can Paperclip run a company with no people?","answer":"No account we found shows that. The project dropped its “zero-human companies” tagline, its maker says people still set direction, approve plans and rewrite instructions, and independent reviews describe review load and drift rather than autonomous success."},{"question":"Is Paperclip secure enough for production?","answer":"Treat it with care. One review counted 12 GitHub security advisories, five rated critical, as of early October 2026, and reported that the Codex adapter defaulted its bypass setting to true. Run it isolated, require approval for actions with outside effects, and check the current advisories yourself."},{"question":"How is Paperclip different from n8n or a coding agent?","answer":"A workflow tool such as n8n runs a fixed sequence of steps, and a coding agent runs one working session. Paperclip sits above agents and controls the organisation around them: who is assigned what, what it may cost, who reviews it and when each agent wakes."}]'::jsonb,
  false,
  74,
  null,
  106,
  true
),
(
  'multi-agent-systems-evidence',
  'Do Multi-Agent AI Systems Work? What the Evidence Says in 2026',
  'Several agents can beat one by 80%, or lose by 70%. The difference is not the model; it is whether the work splits into independent pieces and whether something checks the result.',
  'Controlled studies and the teams that built multi-agent systems agree: they help on parallel work, hurt on sequential work, cost far more tokens, and need a checker.',
  'automation',
  8,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'auditLens',
  '{"primary":"multi-agent systems","secondary":["multi agent ai","single agent vs multi agent","why multi-agent llm systems fail","ai agent orchestration patterns"],"searchVolume":0,"difficulty":"medium","intent":"informational"}'::jsonb,
  '["Across 260 configurations, multi-agent setups ranged from +80.8% on decomposable work to −70.0% on sequential planning, compared with a single agent.","What works in production is one writer, with other agents researching, reviewing or handling separate pieces under a manager.","Multi-agent systems use about 15 times the tokens of chat, against about 4 times for a single agent, so cost scales with the number of agents.","Every documented success depends on a strong automatic check; most business departments do not have one yet.","Before adding agents, ask whether the work splits into independent pieces and how a wrong result would be caught."]'::jsonb,
  '[{"heading":"The short answer: it depends on how parallel the work is","paragraphs":["The clearest controlled evidence comes from a study of 260 configurations: five agent architectures, six benchmarks and three model families. Compared with a single agent, multi-agent performance ranged from +80.8% on decomposable financial reasoning to −70.0% on sequential planning. Architectures without centralised verification propagated errors more, and a predictive model picked the best architecture for 87% of held-out configurations ([Kim et al., arXiv 2512.08296](https://arxiv.org/abs/2512.08296)).","That spread is the whole story in miniature. When a task breaks into independent pieces, several agents working in parallel and reporting to a coordinator can cover more ground than one. When each step depends on the last, extra agents add hand-offs, conflicting assumptions and errors that compound."],"pullQuote":"Most coding tasks have fewer truly parallelizable parts than research."},{"heading":"What the teams that built them learned","paragraphs":["Anthropic''s research system, a lead agent with parallel subagents, beat a single agent by 90.2% on an internal research evaluation, and token usage alone explained 80% of performance variance on one benchmark. The same post warns that the design suits breadth-first research and fits poorly where agents must share context, and that “most coding tasks have fewer truly parallelizable parts than research” ([Anthropic](https://www.anthropic.com/engineering/multi-agent-research-system)).","Cognition argued in June 2025 for single-threaded agents, because “actions carry implicit decisions, and conflicting decisions carry bad results” ([Cognition](https://cognition.com/blog/dont-build-multi-agents)). In April 2026 it narrowed that view after a year of practice: what works is where “writes stay single-threaded and the additional agents contribute intelligence rather than actions”. That means a reviewer with a clean context, a stronger model consulted on hard steps, and a manager splitting work across child agents. Parallel writers “still don''t see meaningful adoption” ([Cognition](https://cognition.com/blog/multi-agents-working)).","Cursor found the same at scale. Flat coordination with locks failed (“Twenty agents would slow down to the effective throughput of two or three”), while planners, workers and a judge worked well enough for hundreds of concurrent agents to write over a million lines for a browser in about a week ([Cursor](https://cursor.com/blog/scaling-agents)). Anthropic''s 16 parallel agents built a 100,000-line C compiler over nearly 2,000 sessions for just under USD 20,000; it builds Linux 6.9 on three architectures, but its output is slower than GCC with optimisations off and the author stresses the verifier must be “nearly perfect” ([Anthropic](https://www.anthropic.com/engineering/building-c-compiler))."]},{"heading":"Why multi-agent systems fail","paragraphs":["A taxonomy built from more than 1,600 annotated traces across seven frameworks found 14 failure modes in three groups: system design problems, misalignment between agents, and weak task verification. The authors also note that gains on popular benchmarks are “often minimal” ([Cemri et al., arXiv 2503.13657](https://arxiv.org/abs/2503.13657)).","The builders'' own write-ups name the same faults in their own systems. Cognition found its manager agents were over-prescriptive and assumed they shared state with the child agents they directed ([Cognition](https://cognition.com/blog/multi-agents-working)). Cursor found that optimistic concurrency made agents risk-averse, that an integrator role added more bottlenecks than it removed, and that long runs needed periodic fresh starts. Gas Town, an open orchestrator, claims it can “scale comfortably to 20-30 agents” but ships a scheduler specifically to prevent “API rate limit exhaustion” ([Gas Town](https://github.com/gastownhall/gastown)), which tells you where the ceiling is felt first.","In plain terms, three things go wrong. Agents work from different pictures of the task because they did not share full context. Two agents make decisions that quietly contradict each other. And nobody checks the combined result against what was actually asked. Claude Code''s own documentation lists the practical version: agent teams are experimental, use “significantly more tokens than a single session”, and for “sequential tasks, same-file edits, or work with many dependencies” a single session is more effective ([Claude Code docs](https://code.claude.com/docs/en/agent-teams.md))."],"bullets":["Missing context: agents act on summaries instead of full traces.","Conflicting actions: two writers make incompatible choices.","No verification: the merged result is never checked against the request.","Coordination loops: agents hand work back and forth and re-open settled decisions."]},{"heading":"The cost: tokens rise with every agent","paragraphs":["Anthropic measured agents using about 4 times the tokens of a chat, and multi-agent systems about 15 times. Claude Code''s documentation says team cost scales roughly linearly with the number of teammates and suggests starting with three to five. The compiler project consumed 2 billion input and 140 million output tokens.","So every added agent has to earn its tokens. The only way to see whether it does is to track cost per ticket, not per month, and compare it with what the work used to cost a person. Vendor productivity claims do not settle the question: Warp cites a customer cutting cost per pull request from USD 80 to USD 30, a vendor claim ([warp.dev](https://www.warp.dev/)), while METR''s randomised trial found experienced developers took 19% longer with AI tools in early 2025 and its late-2025 follow-up found only “very weak evidence” of a speed-up ([METR](https://metr.org/blog/2026-02-24-uplift-update/))."],"callout":{"title":"Benchmarks are moving too","body":"OpenAI stopped reporting SWE-bench Verified on 23 February 2026 after an audit found material flaws in 59.4% of 138 problems and signs of contamination. Read any single benchmark number with care."}},{"heading":"Verification is the real bottleneck","paragraphs":["Look at the successes again: the compiler had a test suite, Cursor had a judge, Cognition has a reviewer agent. Each depends on something that can tell a correct result from an incorrect one without a person reading every line. Long-task capability keeps rising (METR''s newest measured model has a 50% time horizon of about 1,045 minutes, though METR calls figures above 16 hours unreliable), but METR also warns that its tasks are self-contained and automatically scored while “real work is messier” ([METR](https://metr.org/time-horizons/)).","Software has tests. A sales quote, a purchase order or a month-end reconciliation usually does not, which is why moving multi-agent patterns from engineering into business departments is harder than the demos suggest."]},{"heading":"What this means for finance, sales and operations","paragraphs":["Departments differ in how parallel their work is. Lead research across hundreds of accounts, matching many independent records, and reviewing a pile of supplier documents split cleanly, so a coordinator with several workers fits. A single order-to-cash flow, a quote whose price depends on the routing, or a drawing revision is sequential, so one agent with good context and a checker fits better.","An illustrative example, not a customer case: a manufacturer wants agents to chase overdue invoices. Pulling each overdue invoice, its customer history and the last correspondence is parallel and suits several workers. Deciding whether to stop supply to a customer is a single decision with consequences, so it belongs to one agent drafting a recommendation and a named person approving it. The figures in that draft should come from the ledger, calculated by code, not from the model. That is how we design workflows on our [agentic ERP and CRM page](/agentic-erp-crm)."],"bullets":["Does the work split into pieces that do not depend on each other? If not, use one agent.","What will catch a wrong result: a rule, a reconciliation or a named reviewer?","Who approves anything that changes a record or reaches a customer?","What is the acceptance criterion for each ticket, written down before the agent starts?","What does a ticket cost in tokens and review minutes, and is that less than before?"]}]'::jsonb,
  '["ai-agents","multi-agent","evidence","operations"]'::jsonb,
  '["paperclip-ai-review-company-of-agents","mcp-for-erp-crm-agents","context-graphs-decision-traces"]'::jsonb,
  '[{"href":"/research/ai-agent-orchestration-platforms","label":"The full research report","note":"benchmarks, oversight patterns and the open projects to build on"},{"href":"/agentic-erp-crm","label":"Agentic ERP & CRM","note":"specialised agents with approved tools and human approval"},{"href":"/industrial-systems-audit","label":"Book a systems audit","note":"find which of your workflows split cleanly"}]'::jsonb,
  '[{"question":"Are multi-agent systems better than a single AI agent?","answer":"Only for work that splits into independent pieces. One study of 260 configurations found results ranging from +80.8% on decomposable tasks to −70.0% on sequential planning. For sequential work, one agent with full context and a checker usually does better."},{"question":"Why do multi-agent LLM systems fail?","answer":"A study of more than 1,600 traces grouped 14 failure modes into system design problems, misalignment between agents, and weak task verification. In practice agents lack shared context, make conflicting decisions, and nobody checks the combined result."},{"question":"How much more do multi-agent systems cost?","answer":"Anthropic measured multi-agent systems using about 15 times the tokens of a chat, against about 4 times for a single agent, and Claude Code''s documentation says team cost scales roughly with the number of agents. Track cost per completed ticket to see whether extra agents pay for themselves."},{"question":"What multi-agent pattern works in production?","answer":"Keep one agent writing and use others to contribute intelligence rather than actions: a reviewer with a clean context, a stronger model consulted on hard steps, or a manager splitting independent work among child agents, as Cognition and Cursor describe."},{"question":"Can multi-agent AI run business departments such as finance or sales?","answer":"Parts of them. Research, enrichment and matching many independent records suit parallel agents. Decisions with consequences, such as approving credit or a price, suit one agent preparing a draft and a person approving it, with figures calculated from the system of record."}]'::jsonb,
  false,
  70,
  null,
  107,
  true
),
(
  'solidworks-in-browser-streaming-licences',
  'Can You Run SolidWorks in a Browser? Streaming, Licences and Cost',
  'You can stream it, universities do, and it will cost you a GPU by the hour. But Dassault does not certify any VDI platform, and the better answer for most teams is a hub built around the workstation.',
  'SolidWorks does not run natively in a browser. What streaming costs, what Dassault and resellers say about VDI, and the setup that works for small engineering teams.',
  'ops',
  8,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'auditLens',
  '{"primary":"solidworks in browser","secondary":["solidworks vdi","stream cad to browser","solidworks cloud streaming cost","browser based cad"],"searchVolume":0,"difficulty":"medium","intent":"commercial"}'::jsonb,
  '["SolidWorks is a Windows desktop application; it reaches a browser only by streaming from a Windows machine.","A reseller states that Dassault does not test or certify any VDI platform and that remote sessions can fall back to software OpenGL.","GPU cloud desktops list at roughly $0.99 to $2.27 an hour (Vagon) or $310 to $1,029 a month (one Windows 365 GPU listing), before the CAD licence.","Onshape, Zoo and Figma got CAD and design into the browser by building for it, not by porting a desktop app.","For most small teams the practical setup is the licensed workstation plus a web hub that manages files, revisions and approvals around it."]'::jsonb,
  '[{"heading":"The short answer","paragraphs":["No, not natively. SolidWorks is a Windows desktop application, and the only way to use it from a browser tab is to stream the screen of a Windows machine that runs it. That works technically: NC State, for example, delivers SOLIDWORKS Education “through Azure Virtual Desktop and Amazon AppStream” ([NC State Engineering IT](https://it.engr.ncsu.edu/software/?p=764)). Whether it is supported, licensed and pleasant to use for daily commercial design work is a different question, and the answer is mostly no.","This post sets out what the vendor''s channel says, what streaming costs, how browser-native CAD products solved the problem instead, and the setup we would recommend to a small engineering team that wants its CAD work visible from a central web hub."]},{"heading":"What Dassault and its resellers say about VDI","paragraphs":["A reseller article dated 12 November 2026 is direct: “Dassault Systèmes only supports the use of Windows OS and Windows installed on Mac Parallels”, it “does not test or certify any VDI platforms”, and the reseller''s own support “cannot provide any assistance with the setup and configuration of VDIs”. The problems it lists are practical ones: virtual GPU driver failures, licences not returned properly, file corruption, and remote desktop sessions that fall back to a software OpenGL mode that “essentially bypasses your graphics card altogether” ([GoEngineer](https://www.goengineer.com/blog/unconventional-solidworks-environments-risks-and-consequences)).","Hosting providers are more optimistic and say SolidWorks licences “may be used in hosted environments, depending on the license agreement”, which is marketing from a company selling hosting ([Ace Cloud Hosting](https://www.acecloudhosting.com/blog/right-way-to-run-solidworks-remotely/)). We could not read the SolidWorks licence agreement itself, so we cannot quote its virtualisation clauses. Read your own agreement before streaming a commercial seat."],"callout":{"title":"Adobe is more permissive, with a catch","body":"Adobe says named-user licences “can be deployed in a virtualized environment, whereas Shared Device License (SDL) is not permissible”, in an as-is model with best-effort support. Streaming Photoshop from a named-user VM is allowed; being supported is not promised."}},{"heading":"How streaming works, and what a seat costs","paragraphs":["There are two routes. You can rent a GPU desktop in the cloud and install your licensed CAD on it, or you can stream a machine you already own. For Linux desktop apps there are mature open stacks (Selkies, KasmVNC, Xpra); for Windows apps on your own machine, Apache Guacamole is a clientless HTML5 gateway to RDP, VNC and SSH, Apache-2.0 licensed ([Apache Guacamole](https://guacamole.apache.org/releases/1.6.0/)).","Streaming a Linux tool is easier and riskier than it looks. LinuxServer publishes ready images that stream a single application, FreeCAD among them, to a browser tab; a GPU is optional because “the CPU pipeline is fast enough for smooth sessions on modest hardware”. The same page warns that “by default there is no authentication” and that anyone who reaches the interface can get root inside the container ([linuxserver/docker-freecad](https://github.com/linuxserver/docker-freecad)). Kasm Workspaces Community is free for up to five concurrent sessions, which is enough for a pilot. None of these stacks publishes a measured latency figure; every vendor describes it only in words.","List prices for the cloud route, read on 22 November 2026, are below. The monthly figures are our arithmetic for a seat used 160 hours a month, not quotes. For comparison, a non-GPU streamed Windows seat on Amazon WorkSpaces Applications starts at $0.10 an hour plus a $4.19 monthly Microsoft user fee, which suits office tools, not CAD."],"bullets":["Vagon “Planet”, NVIDIA T4 16 GB: $0.99 an hour plus a $7.99 monthly plan; “Spark” and “Flame”, NVIDIA A10G 24 GB: $1.67 and $2.27 an hour ([Vagon](https://vagon.io/pricing)). Roughly $160 to $360 a month at 160 hours.","Windows 365 GPU Cloud PCs: $310, $537 or $1,029 per user per month on one Microsoft listing, while other regional pages show “Variable” ([Microsoft](https://www.microsoft.com/en-us/windows-365/all-pricing?rtc=1)).","Parsec Teams or Enterprise on your own hardware: $35 or $45 per user per month; the free plans are personal and non-commercial only ([Parsec](https://parsec.app/pricing)).","Self-hosted NVIDIA vGPU: an RTX Virtual Workstation licence at $250 per concurrent user per year, on top of the servers ([NVIDIA](https://docs.nvidia.com/vgpu/packaging-pricing-licensing-guide/latest)).","Add the CAD licence itself to every one of these."]},{"heading":"What browser-native CAD did instead","paragraphs":["The products that put CAD and design in the browser did not port a desktop program. Onshape runs its geometry kernels (Parasolid and D-Cubed) on servers and sends triangles to the browser, rendered with WebGL; it does not stream pixels ([Onshape](https://www.onshape.com/en/blog/how-does-onshape-really-work)). Zoo Design Studio does the opposite: “The 3D view in Design Studio is just a video stream from our hosted geometry engine” ([Zoo](https://github.com/KittyCAD/modeling-app)). Figma compiled its own C++ renderer to WebAssembly and moved it to WebGPU, with a fallback to WebGL ([Figma](https://www.figma.com/blog/figma-rendering-powered-by-webgpu/)).","Ports of existing desktop CAD to WebAssembly appeared in 2026: a community FreeCAD build ran in Chrome but failed in Firefox 155 and 156 and is not an official build ([Qt forum](https://forum.qt.io/post/840221)), and LibreCAD-Web needs a recent Chromium browser. They are impressive demonstrations, and useful as viewers, but not a place to do a day''s design work."]},{"heading":"The agent route: vendor MCP servers, not screen control","paragraphs":["If the goal is to let an AI agent work with your CAD data, screen control is the weakest option. On Windows Agent Arena, reported scores for computer-use agents run from 50.6% to 63.5%, and on multi-application Windows tasks every agent tested scored under 21% ([WindowsWorld](https://aclanthology.org/2026.findings-acl.750.pdf)).","Vendors are building a better door. Autodesk ships a local Fusion MCP server that turns a running Fusion session into an endpoint for agents, a cloud Fusion Data MCP server that needs no install, and a Fusion Compute MCP in public beta ([Autodesk](https://www.autodesk.com/products/fusion-360/blog/introducing-the-fusion-mcp/)). Autodesk''s Automation API already runs AutoCAD, Inventor, Revit and Fusion headless in the cloud ([Autodesk Platform Services](https://aps.autodesk.com/en/docs/design-automation/v3/developers_guide/overview/)). Adobe announced local MCP integrations for Photoshop and Illustrator with a private beta in early 2027. We found no official SolidWorks MCP server."]},{"heading":"A practical setup for a small engineering team","paragraphs":["An illustrative setup, not a customer case. A twelve-person machine shop has three SolidWorks seats. Instead of streaming them, it keeps SolidWorks on the three licensed workstations and makes the web hub the place where everything around the CAD file lives: the released revision, the BOM that came from it, the work orders that used it, the CAM program reference and the inspection result. People outside engineering see a viewer and a status, not a CAD seat. When the design lead works from home, a remote-desktop connection to their own workstation, through Guacamole or Parsec, is a choice they make, not the architecture.","That is the pattern we describe on our [CAD/CAM and CNC integration page](/cad-cam-cnc-integration): link drawings, revisions and BOMs to orders and production without replacing the CAD tool. The full comparison of embedding, streaming and driving every kind of tool is in the [research report](/research/embed-stream-integrate-specialist-software)."],"bullets":["Keep CAD on licensed workstations; do not promise “SolidWorks in a tab”.","Export a neutral file (STEP, PDF drawing) on release and attach it to the revision in the hub.","Give non-engineers a browser viewer, not a seat.","If you stream, use the vendor''s licence terms in writing and a machine you control.","Watch for vendor MCP servers; they are a safer path for agents than screen control."]}]'::jsonb,
  '["cad","solidworks","remote-access","manufacturing"]'::jsonb,
  '["text-to-cad-benchmarks-2026","mcp-apps-generative-ui-a2ui","open-source-licence-risk-agpl-bsl-sspl"]'::jsonb,
  '[{"href":"/research/embed-stream-integrate-specialist-software","label":"The full research report","note":"embedding, streaming and driving every kind of tool from one hub"},{"href":"/cad-cam-cnc-integration","label":"CAD/CAM & CNC integration","note":"revisions, BOMs and programs linked to orders"},{"href":"/industrial-systems-audit","label":"Book a systems audit","note":"map your CAD seats and the handoffs around them"}]'::jsonb,
  '[{"question":"Can SolidWorks run in a web browser?","answer":"Not natively. It can be streamed from a Windows machine to a browser tab, and some universities do this under education licences, but a reseller states that Dassault does not test or certify any VDI platform."},{"question":"Does SolidWorks work on a virtual desktop (VDI)?","answer":"It can, but it is not certified. Reported problems include virtual GPU driver failures, licences not returned properly, file corruption and remote sessions falling back to software OpenGL. Check your licence agreement before relying on it."},{"question":"How much does a cloud GPU workstation for CAD cost?","answer":"List prices in November 2026 ran from $0.99 to $2.27 an hour on Vagon and $310 to $1,029 per user per month on one Windows 365 GPU listing, before the CAD licence. At 160 hours a month that is roughly $160 to over $1,000 a seat."},{"question":"What is the best browser-based CAD?","answer":"Products built for the browser, such as Onshape (server-side geometry, rendered with WebGL) and Zoo Design Studio (a video stream from a hosted engine), work better than desktop CAD ported or streamed into a tab. Which suits you depends on your parts and your existing files."},{"question":"Can AI agents operate SolidWorks?","answer":"Only through screen control or the desktop API today; we found no official SolidWorks MCP server. Screen-control agents score under 21% on multi-application Windows tasks, so keep a person in the loop and prefer vendor APIs where they exist."}]'::jsonb,
  false,
  72,
  null,
  108,
  true
),
(
  'mcp-apps-generative-ui-a2ui',
  'MCP Apps vs A2UI vs AG-UI: Generative UI Protocols Explained',
  'Agents now return interfaces, not just text. Three open protocols decide who draws that interface, where its code runs, and what your product can check before showing it.',
  'MCP Apps, Google''s A2UI and AG-UI let AI agents show interactive UI. How each works, what a host must check for security, and which to choose for your product.',
  'automation',
  8,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'layerStack',
  '{"primary":"mcp apps","secondary":["a2ui","ag-ui protocol","generative ui","mcp apps vs a2ui"],"searchVolume":0,"difficulty":"low","intent":"informational"}'::jsonb,
  '["MCP Apps (stable since 26 January 2026) lets a tool return its own HTML view, rendered in a sandboxed iframe and talking to the host over JSON-RPC.","A2UI 1.0 (Google, November 2026) lets the agent describe UI that your app draws with its own registered components.","AG-UI is an event protocol between an agent backend and a frontend; it can carry A2UI payloads.","MCP Apps requires servers to declare every domain a view may reach, and hosts must not allow undeclared ones.","Use declarative UI where your design, permissions and audit must apply; use MCP Apps for third-party tools that bring their own interface."]'::jsonb,
  '[{"heading":"Why agent interfaces needed a standard","paragraphs":["For two years, an AI agent''s answer was text. That is fine for a summary and poor for a task: approving a purchase order, choosing between three quotes or editing a schedule needs buttons, tables and forms. Each chat product invented its own way to show them, which meant every tool vendor built the same widget several times.","The plumbing underneath changed at the same time. The Model Context Protocol revision of 28 July 2026 made the core stateless: no session ids and no initialise handshake, with every request carrying its protocol version and client capabilities, and long-running work moved into a tasks extension ([MCP changelog](https://modelcontextprotocol.io/specification/2026-07-28/changelog)). Agent-to-agent hand-off got its own stable standard, A2A v1.0, in March 2026 ([AAIF](https://aaif.io/blog/a2a-joins-aaif)). That left one gap: how an agent shows a person something they can act on.","By late 2026 three open protocols had settled the question from different directions. MCP Apps standardises a tool returning its own interface. A2UI standardises an agent describing an interface that your application draws. AG-UI standardises the live event stream between an agent and a frontend. They overlap, and they can be combined, but they make different choices about who controls the pixels."]},{"heading":"MCP Apps: a tool''s own view, in a sandbox","paragraphs":["MCP Apps was proposed on 21 November 2025 ([MCP blog](https://blog.modelcontextprotocol.io/posts/2025-11-21-mcp-apps/)) and its specification is marked stable as of 26 January 2026. A tool links to a UI resource with a ui:// address and the MIME type text/html;profile=mcp-app. The host renders it inside a sandbox; web hosts must use a sandbox proxy on a different origin. The view talks to the host with JSON-RPC 2.0 over postMessage, calling tools, reading resources, opening links or asking for fullscreen, and the host pushes the tool''s input and result to it. A visibility setting decides whether the model, the view or both may call each tool ([MCP Apps specification](https://raw.githubusercontent.com/modelcontextprotocol/ext-apps/main/specification/2026-01-26/apps.mdx)).","Adoption came quickly: “ChatGPT implements the open MCP Apps standard for UI returned by an MCP server”, keeping its older template field as an alias and its own window.openai object for things the shared standard lacks, such as checkout and file upload. Its advice to developers is worth repeating: “Keep tools useful without UI” ([OpenAI Apps SDK](https://developers.openai.com/apps-sdk/mcp-apps-in-chatgpt)). Early-2026 forum threads report that some OpenAI extensions were still needed for CSP and widget state; those are unverified user reports.","A view can ask to be shown inline in the conversation, fullscreen or as a picture-in-picture panel, and the host decides. The SDK repository reached v2.1.0 on 10 November 2026 ([ext-apps](https://github.com/modelcontextprotocol/ext-apps)), and the community project it grew from, mcp-ui, remains available under Apache-2.0 ([mcp-ui](https://github.com/MCP-UI-Org/mcp-ui)). Because the view is ordinary HTML, a tool vendor can reuse the interface it already has, which is the main reason to choose this route."]},{"heading":"A2UI: the agent describes, your app draws","paragraphs":["Google''s A2UI 1.0, announced on 11 November 2026, is “the first stable version of our open protocol for generative UI”. The agent describes what to show and the application draws it “with its own native components”, limited to “the components you register”. Renderers exist for React, Angular, Lit, Flutter, SwiftUI and Jetpack Compose; version 1.0 adds two-way function calls and accessibility; and “the web and Flutter renderers also work inside MCP Apps”. Google names Atlassian (Jira), Alation, ByteDance and its own Gemini products as users ([Google Developers Blog](https://developers.googleblog.com/en/a2ui-10-build-delightful-fast-reliable-agentic-experiences/)). It is Apache-2.0 ([google/A2UI](https://github.com/google/A2UI)).","The design choice matters. With A2UI no third-party code runs in your page: the agent can only ask for components you have already built, styled and permissioned. You lose flexibility and gain control."],"pullQuote":"The agent can only ask for components you have already built."},{"heading":"AG-UI and the AI SDK: the transport and the React route","paragraphs":["AG-UI (MIT) is “an open, lightweight, event-based protocol” between an agent backend and a frontend: streaming chat, typed shared state with event-sourced diffs, frontend tool calls, and interrupts to “pause, approve, edit, retry, or escalate mid flow without losing state”. It positions itself beside the others: MCP connects agents to tools, A2A connects agents to agents, AG-UI connects agents to users ([AG-UI docs](https://docs.ag-ui.com/introduction)). A2UI defines no transport of its own, and Google''s guide with CopilotKit carries A2UI payloads as AG-UI events ([Google Developers Blog](https://developers.googleblog.com/build-generative-ui-apps-with-a2ui-copilotkit-agents/)).","The Vercel AI SDK takes the simplest route for teams already on React: “Generative UI is the process of connecting the results of a tool call to a React component”. The model returns tool data and your code chooses the component ([AI SDK docs](https://ai-sdk.dev/docs/ai-sdk-ui/generative-user-interfaces))."]},{"heading":"What a host must check before rendering anything","paragraphs":["Any interface an agent returns is content from outside your product, and it should be treated that way. MCP Apps writes the rules into the specification: servers declare the domains a view may connect to, load resources from, frame or use as a base URL, and any device permissions it needs (camera, microphone, geolocation, clipboard write). When nothing is declared the default is default-src ''none''. Hosts “may restrict further but must not allow undeclared domains”, and should “validate, log, and reject malformed view messages” ([MCP Apps specification](https://raw.githubusercontent.com/modelcontextprotocol/ext-apps/main/specification/2026-01-26/apps.mdx)). A2UI reaches the same goal by a different road: because only registered components can be drawn, there is no foreign code to contain, only data to validate against the components you allow."],"bullets":["Render third-party views on a separate origin, never in your own page''s context.","Allow only the domains the server declared, and fewer if you can.","Log every message a view sends, and reject anything malformed.","Keep consequential actions (approving, paying, sending) behind your own approval step, not a button inside a third-party view.","Prefer tools that work headless, so an agent can act without the view and a person can audit what it did."],"callout":{"title":"Not yet in the standard","body":"MCP Apps explicitly defers embedding an external URL, persisting view state and view-to-view communication. Plan around those gaps rather than assuming them."}},{"heading":"Which to use when","paragraphs":["An illustrative example, not a customer case: a manufacturer''s operations hub wants an agent to propose next week''s machine schedule. The schedule view must use the hub''s own styles, show only the work orders the user may see, and send any change through the hub''s approval rule. That is a job for declarative UI (A2UI, or tool results mapped to your own React components with the AI SDK), because the hub stays in control of design, permissions and audit. The same hub might also show a third-party design tool''s preview, which arrives as an MCP Apps view inside a sandbox, because that vendor owns its interface.","Our rule of thumb: build the tools first, headless, and add UI as an optional surface on the same tools. That keeps people and agents acting through the same server-side actions, which is how we approach agents on our [agentic ERP and CRM page](/agentic-erp-crm). The full adapter contract, from identity to sandboxing, is in our [research report on embedding and integration](/research/embed-stream-integrate-specialist-software)."],"bullets":["Your own product''s screens, built from your design system: A2UI or AI SDK tool-to-component mapping.","A third-party tool''s interface inside your product or a chat client: MCP Apps.","Streaming chat, shared state and pause-for-approval between agent and frontend: AG-UI as the transport.","Agent-to-agent hand-off: A2A, not a UI protocol."]}]'::jsonb,
  '["ai-agents","mcp","generative-ui","architecture"]'::jsonb,
  '["mcp-for-erp-crm-agents","solidworks-in-browser-streaming-licences","prompt-injection-crm-ai-agents"]'::jsonb,
  '[{"href":"/research/embed-stream-integrate-specialist-software","label":"The full research report","note":"the complete tool-adapter contract and its hard limits"},{"href":"/agentic-erp-crm","label":"Agentic ERP & CRM","note":"agents that act through approved tools"},{"href":"/factory-graph","label":"Factory Graph","note":"one governed layer over the systems you already run"}]'::jsonb,
  '[{"question":"What is MCP Apps?","answer":"An extension of the Model Context Protocol, stable since 26 January 2026, that lets a tool return an interactive HTML view. The host renders it in a sandboxed iframe and the view talks to the host by JSON-RPC over postMessage. ChatGPT implements it."},{"question":"What is A2UI?","answer":"Google''s open, Apache-2.0 protocol for generative UI. Version 1.0 was announced on 11 November 2026. The agent describes the interface and the application draws it with its own registered components, with renderers for React, Angular, Lit, Flutter, SwiftUI and Jetpack Compose."},{"question":"What is the difference between AG-UI and MCP?","answer":"MCP connects agents to tools and data. AG-UI is an event protocol between an agent backend and a user-facing frontend, covering streaming chat, shared state, frontend tool calls and interrupts. They are complementary, and AG-UI can carry A2UI payloads."},{"question":"Is MCP Apps secure?","answer":"The specification is designed for it: views run on a separate origin, servers must declare every domain the view may reach, and hosts must not allow undeclared ones. The host still has to enforce those rules and keep consequential actions behind its own approvals."},{"question":"Should I use MCP Apps or A2UI in my product?","answer":"Use A2UI-style declarative UI, or your own components through the AI SDK, where your design, permissions and audit must apply. Use MCP Apps when a third-party tool brings its own interface that you are willing to run in a sandbox."}]'::jsonb,
  false,
  66,
  null,
  109,
  true
),
(
  'saas-sprawl-statistics-2026',
  'SaaS Sprawl Statistics 2026: How Many Apps Companies Really Run',
  'Okta says 72, BetterCloud says 164, Zylo says 305. All three are right about different things. Here is what each number measures, what sprawl costs, and a one-afternoon audit you can run this week.',
  'Three respected sources count company SaaS apps at 72, 164 and 305. Why they differ, what sprawl really costs in licences, renewals and security, and how to audit yours.',
  'ops',
  9,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'auditLens',
  '{"primary":"SaaS sprawl statistics","secondary":["how many SaaS apps does a company use","SaaS licence waste","SaaS management 2026","shadow IT AI apps"],"searchVolume":0,"difficulty":"medium","intent":"informational"}'::jsonb,
  '["The three headline counts (72, 164, 305) measure different things: single sign-on, a survey of IT staff, and spend discovery at large companies.","Consolidation is over. App counts are rising again, driven by AI tools, and fastest in the mid-market.","Licences are the visible cost; renewals, offboarding gaps and manual hand-offs between apps are the larger ones.","Zylo''s dollar averages are enterprise numbers. Use its per-employee median and your own card statements instead.","A one-afternoon audit (sources, owners, utilisation, renewals, offboarding, AI features) finds most of the waste."]'::jsonb,
  '[{"heading":"Three numbers that disagree, and why all three are right","paragraphs":["Ask how many SaaS apps a company runs and you will get three very different answers from three serious sources. Okta''s Businesses at Work 2026, based on its customers'' data from 1 November 2024 to 31 October 2025, counts a global average of 98 apps per company, down 3% from 101. Companies under 2,000 employees average 72, companies above that average 259, and tech startups 46 ([Okta](https://www.okta.com/ja-jp/newsroom/press-releases/okta-businesses-at-work2026/)).","BetterCloud''s 2026 State of SaaS, a survey of 525 IT and security professionals published on 15 July 2026, says app counts rose 11% overall and 41% in the mid-market, from 116 to 164 ([BetterCloud](https://www.bettercloud.com/monitor/the-2026-state-of-saas-report/)). Zylo''s 2026 SaaS Management Index, built from more than 40 million licences and $75B of spend under management, puts the average portfolio at 305 apps and the median at 240, flat year on year ([Zylo](https://zylo.com/news/2026-saas-management-index)). Torii lists BetterCloud''s 2026 average as 118, up from 106 ([Torii](https://www.toriihq.com/saas-statistics)).","The gap is method, not error. Okta can only see apps that are wired to single sign-on, so its number is a floor: anything a team signs up for with a card and a password is invisible to it. BetterCloud asks IT people, who report what they know about. Zylo discovers apps from spend and expense data at mostly large customers, so it catches shadow purchases and skews high."],"callout":{"title":"The defensible SME range","body":"For a small or mid-sized company, Okta''s startup and sub-2,000 figures (roughly 45 to 75 managed apps) are the most defensible starting point, with more unmanaged apps on top. No source found in our research gives app counts or SaaS spend for Indian SMEs specifically."}},{"heading":"Consolidation ended in 2025, and AI apps are why","paragraphs":["For a few years the count fell. BetterCloud''s own series peaked at 130 apps in 2022, dropped to 112 in 2023 and 106 in the 2025 report (as summarised from BetterCloud''s pages) ([BetterCloud 2025](https://www.bettercloud.com/monitor/2025-state-of-saas-trends/)). The 2026 survey reverses that, and the reason is visible in the detail: an average of 27 AI-powered apps per organisation, 22% of the portfolio, and only 56% of apps in use with IT approval.","Zylo''s numbers say the same thing in money. AI-native app spend rose 108% overall and 393% at organisations above 10,000 employees; the average organisation spends $1.2M a year on AI-native apps and holds 7 generative-AI apps; 78% of IT leaders had unexpected consumption or AI charges; 61% cut projects because of unplanned SaaS cost increases; and 77% found AI features or apps running without IT''s knowledge ([Zylo](https://zylo.com/blog/saas-statistics)).","Two other Zylo figures explain why IT cannot simply say no. Business units control 81% of SaaS spend, while IT directly manages 15%, and expensed SaaS rose from 1% to 3.7% of spend. Large enterprises add 21 applications a month ([Zylo](https://zylo.com/news/2026-saas-management-index))."]},{"heading":"What sprawl actually costs: four bills, not one","paragraphs":["Licence waste is the bill everyone talks about. Zylo measured utilisation at 54% in 2025, up from 47%, and puts waste at $19.8M a year for the average organisation it tracks, down from $20.9M ([Zylo](https://zylo.com/blog/saas-statistics)). It is real, but in our view it is the smallest of four costs."],"bullets":["Unused seats: roughly 46% of licences not in use by Zylo''s utilisation figure, or 36% against “industry-recommended utilization levels” in its own release.","Renewal overhead: 211 renewals a year at the average Zylo customer, and 79% of IT leaders saw a price increase at renewal.","Security exposure: only one in four organisations automates offboarding, and 18% had a breach caused by an offboarded user who still had access ([BetterCloud](https://www.bettercloud.com/monitor/the-2026-state-of-saas-report/)). Security and governance is now the top SaaS challenge for 47% of respondents, up from 28%.","Missing orchestration: 90% lack true cross-app orchestration, and 62% of IT leaders say manual work blocks strategic projects. That is people retyping the same customer, order or employee between apps."],"callout":{"title":"Pricing is moving to metering","body":"On top of seats, agent features are increasingly metered: Asana caps AI Teammates at 5 requests per user a month before charging per request, and Mattermost''s free commercial mode caps agent queries at 250 a month. A tool count that holds steady can still produce a rising, less predictable bill."}},{"heading":"Why the enterprise averages do not fit an SME","paragraphs":["Zylo''s average organisation spends $55.7M a year on SaaS (median $20.6M). Those are large-enterprise figures and should not be quoted to a 60-person manufacturer. The more portable number is Zylo''s median spend per employee, $9,455 a year ([Zylo benchmarks](https://zylo.com/benchmarks)), and even that should be checked against your own statements.","In India the list prices are lower and the shape is different. Google Workspace Starter is ₹270 per user a month and Slack Pro ₹245.25 on yearly billing ([Google Workspace India](https://workspace.google.com/intl/en_in/pricing.html); [Slack India](https://slack.com/intl/en-in/pricing)). As an illustration only: a 50-person company on just those two tools pays about ₹25,762 a month before GST, before it has bought any accounting, HR, CRM or design software. Each additional tool adds its own login, its own copy of the employee list and its own renewal date.","The point for an SME is not that it runs 300 apps. It is that each app it adds creates another place where the same customer, order or person is stored, and another hand-off someone has to do by hand. Our [back-office software map](/research/back-office-software-open-source-alternatives) lays out which department each tool belongs to."]},{"heading":"A one-afternoon SaaS audit checklist","paragraphs":["This checklist is ours, not from any of the reports above. It is designed so one person with access to the card statements and the admin consoles can finish it in an afternoon."],"bullets":["List every app from three sources, not one: the single sign-on console, company card and expense statements, and a short message to each team lead asking what they use. Okta-style lists miss card purchases; card statements miss free tools.","Name one owner per app, and the department it serves. An app with no owner is the first candidate to cancel.","Record seats bought against seats used in the last 30 days. Anything below roughly half is worth a conversation before the next renewal.","Put every renewal date in one calendar with a reminder 60 days ahead, because price increases are announced at renewal.","Check offboarding: pick the last three people who left and confirm their access is gone from every app on the list.","Mark every app that has switched on AI features or agents, what data they can read, and whether usage is metered.","Find duplicates by function: two chat tools, three places that store customer records, two ways to sign documents.","For each duplicate, decide which one is the record and which one only reads from it."]},{"heading":"Where consolidation actually helps","paragraphs":["Cutting apps is not the goal in itself. The sprawl costs that matter most (renewals, offboarding and hand-offs) are addressed by three things: one login, one directory of people, and shared records that several departments read from instead of copying. Germany''s openDesk and France''s La Suite show the first two can be built from open-source parts, and also that sharing data between apps is the slow, hard part ([openDesk architecture](https://docs.opendesk.eu/operations/architecture)).","For a manufacturer, the shared records are the ones that cross departments: the order, the part revision, the work order, the inspection lot, the invoice. That is the starting point of our [Factory Graph](/factory-graph) work: relate those records across the systems you already run, without replacing them. If you want to see where your own stack stands, an [industrial systems audit](/industrial-systems-audit) maps the systems and the hand-offs between them. And before you swap a paid tool for an open-source one, read our guide to [open-source licence risk](/blogs/open-source-licence-risk-agpl-bsl-sspl): several popular “open” tools restrict exactly the use you have in mind."],"pullQuote":"Sprawl is not a count. It is the number of places the same customer is stored, and the number of people retyping it."}]'::jsonb,
  '["saas","it operations","cost control","research"]'::jsonb,
  '["open-source-licence-risk-agpl-bsl-sspl","ai-support-agent-pricing-per-resolution","procurement-automation-requisition-to-receipt"]'::jsonb,
  '[{"href":"/research/back-office-software-open-source-alternatives","label":"Back-office software map","note":"the full research report, department by department"},{"href":"/factory-graph","label":"Factory Graph","note":"one governed layer over the systems you already run"},{"href":"/industrial-systems-audit","label":"Industrial systems audit","note":"map your systems and the hand-offs between them"}]'::jsonb,
  '[{"question":"How many SaaS apps does the average company use in 2026?","answer":"It depends on the source. Okta counts 98 apps behind single sign-on on average, 72 at companies under 2,000 employees. BetterCloud''s survey puts mid-market organisations at 164. Zylo, which finds apps from spend data at mostly large customers, reports an average of 305 and a median of 240."},{"question":"What percentage of SaaS licences go unused?","answer":"Zylo measured licence utilisation at 54% in 2025, up from 47% in 2024, which means roughly 46% of licences were not in use. Its news release states it differently, as 36% unused against industry-recommended utilisation levels."},{"question":"Why is SaaS sprawl growing again?","answer":"Mostly AI tools. BetterCloud''s 2026 survey found an average of 27 AI-powered apps per organisation, 22% of the portfolio, and Zylo reports AI-native app spend up 108% in a year. Its mid-market count jumped 41% in one year after several years of consolidation."},{"question":"Are Zylo''s dollar figures relevant to a small business?","answer":"Not directly. Zylo''s averages, such as $55.7M of annual SaaS spend and $19.8M of licence waste, come from large enterprises. The safer number to compare against is its median of $9,455 per employee a year, and even that should be checked against your own spend."},{"question":"What is the biggest hidden cost of SaaS sprawl?","answer":"Usually not the licences. Renewal overhead, security exposure from unsanctioned apps and slow offboarding, and the manual work of moving data between apps that do not talk to each other tend to cost more. BetterCloud found 90% of organisations lack true cross-app orchestration."}]'::jsonb,
  false,
  74,
  null,
  110,
  true
),
(
  'open-source-licence-risk-agpl-bsl-sspl',
  'AGPL, BSL, SSPL and Fair-Code: Open-Source Licence Risk Explained',
  'Some “open source” tools cannot be embedded in a product, some cannot be hosted for others, and some changed their licence last year. A plain guide to the four tiers, with the 2024–2026 cases that matter.',
  'Permissive, copyleft, AGPL and source-available licences carry very different obligations. What each tier allows, which popular tools changed terms, and how to hold each one.',
  'ops',
  10,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'layerStack',
  '{"primary":"AGPL vs BSL licence risk","secondary":["is n8n open source","SSPL open source","fair-code licence","AGPL commercial use","business source license explained"],"searchVolume":0,"difficulty":"medium","intent":"informational"}'::jsonb,
  '["There are four practical tiers: permissive, weak copyleft, GPL/AGPL, and source-available or fair-code.","AGPL is usually safe as an unmodified, separate service and risky once modified and offered to others over a network.","Source-available licences (Sustainable Use, Elastic, BSL, vendor agreements) forbid specific commercial uses, often the exact one a product needs.","Licences move: tldraw, Zitadel, NocoDB, NocoBase, Camunda, Cal.com, EMQX and ThingsBoard all changed terms between 2024 and 2026.","Open-core projects keep SSO, audit logs and fine-grained roles in an enterprise directory under a separate licence."]'::jsonb,
  '[{"heading":"One question decides the tier: what are you going to do with it?","paragraphs":["Licence risk depends less on the licence''s name than on what you plan to do: use the software internally, run it as a separate service beside your product, link it into your own code, modify it, or host it for other companies. The same licence can be harmless for one of these and a serious problem for another.","Across the projects in our [back-office software map](/research/back-office-software-open-source-alternatives), licences fall into four practical tiers. Permissive licences (MIT, Apache-2.0, BSD) let you embed, modify and white-label. Weak copyleft (LGPL, MPL, EPL) lets you link or call freely but asks you to publish changes to the library itself. Strong copyleft (GPL, AGPL) is best kept at arm''s length as a separate, unmodified program. Source-available and fair-code licences forbid specific commercial uses outright. What follows is a plain reading of public licence texts and policies, not legal advice."]},{"heading":"Permissive and weak copyleft: the easy tiers","paragraphs":["Most of the shared infrastructure a business needs exists under permissive terms: Keycloak for identity, Zulip for chat, Jitsi and LiveKit for video, Grist for spreadsheet-databases, Superset for BI, Temporal for durable workflows and Docling for document parsing ([Keycloak](https://github.com/keycloak/keycloak); [Temporal](https://github.com/temporalio/temporal); [Docling](https://github.com/docling-project/docling)). These can be built into a product and branded as part of it, with attribution.","Weak copyleft adds one obligation: share changes to the library itself. Odoo Community is LGPL-3.0, Collabora Online and Penpot are MPL-2.0, and OpenBoxes is EPL-1.0. Germany''s openDesk shows how far this tier stretches: openDesk''s own code is Apache-2.0 while its components keep their own AGPL, GPL, LGPL, MPL or MIT licences, run side by side ([openDesk](https://docs.opendesk.eu/operations/introduction)).","Even the easy tiers hide two traps. The first is the edition split: Odoo Community is LGPL, but Odoo Enterprise “can only be used (executed, modified, executed after modifications) with a valid Odoo Enterprise Subscription” for the right number of users, so a feature that exists only in Enterprise is commercial software whatever the repository says ([Odoo licences](https://www.odoo.com/documentation/19.0/legal/licenses.html)). The second is a free tier with the useful parts removed. Mattermost''s Team Edition is MIT, but for fewer than 250 users and without single sign-on, and its free commercial mode caps viewable history at 10,000 messages and agent queries at 250 a month ([Mattermost](https://docs.mattermost.com/product-overview/editions-and-offerings.html)). A permissive licence on a stripped edition is still a stripped edition."]},{"heading":"GPL and AGPL: run it beside you, not inside you","paragraphs":["Many of the strongest business applications are GPL or AGPL: ERPNext, Frappe HR and OpenProject are GPL-3.0; Plane, Nextcloud, Documenso, DocuSeal, Lago, Zammad and Metabase''s core are AGPL. The Free Software Foundation''s reasoning on what counts as one program is the key. It treats “pipes, sockets and command-line arguments” as communication mechanisms normally used between two separate programs, while programs designed to run linked together in a shared address space are almost surely one program, and it says the analysis “is unchanged by the involvement of containers” ([GNU GPL FAQ](https://www.gnu.org/licenses/gpl-faq.html)).","AGPL adds a network clause: a modified version must offer all users interacting with it over a network an opportunity to receive the source. That is why some buyers refuse it entirely. Google''s policy says AGPL code “MUST NOT be used at Google”, because a product depending on it may have to release its complete source and the obligation is triggered if the product “can be accessed over a remote network interface” ([Google](https://opensource.google/documentation/reference/using/agpl-policy))."],"bullets":["Using an AGPL tool internally, unmodified: generally low risk. The network clause bites when you modify the software and other people use it over a network.","Running it unmodified as a separate service beside your product: the common pattern, consistent with the FSF''s view of separate programs talking over sockets.","Modifying it and offering the result to customers: the modified source must be offered to those users.","Selling to an enterprise whose policy bans AGPL: the licence analysis no longer matters; you need a different component."],"callout":{"title":"The common safe pattern","body":"Run the AGPL application unmodified, as its own service, behind your login, and talk to it over its API. If you must change it, publish those changes. If an enterprise customer bans AGPL, you need a different component, whatever the legal analysis says."}},{"heading":"Source-available and fair-code: the tier that looks open","paragraphs":["This is where most surprises happen, because the code is on GitHub and the project calls itself open. The licence says otherwise."],"bullets":["n8n''s Sustainable Use License allows use “only for your own internal business purposes or for non-commercial or personal use”, and files with .ee need an enterprise licence ([n8n](https://github.com/n8n-io/n8n)). NocoDB adopted the same licence; its licence file is dated 29 January 2026 ([NocoDB](https://github.com/nocodb/nocodb)).","Akaunting''s Business Source License limits production use to two users, one company or 1,000 invoices, bans white-labelling and bans offering it as an “Accounting Service”; each release converts to GPLv3 after four years ([Akaunting](https://github.com/akaunting/akaunting)).","Outline''s Business Source License 1.1 bans using it for a “Document Service” offered to third parties ([Outline](https://github.com/outline/outline)). Invoice Ninja and Airbyte are under the Elastic License 2.0.","Camunda 8, from version 8.6 (8 October 2024), is free for development and testing only; production needs a licence ([Camunda](https://camunda.com/blog/2024/04/licensing-update-camunda-8-self-managed/)). Operaton is the community-owned Apache-2.0 engine built on Camunda 7.","Pimcore moved to its own Pimcore Open Core License from Platform 2025.1, and Directus uses a licence that allows any purpose except a “Competing Use” ([Pimcore](https://pimcore.com/en/resources/blog/breaking-free-pimcore-says-goodbye-to-gpl-and-enters-a-new-era-with-pocl); [Directus](https://github.com/directus/directus)).","The SSPL “is not an open source license”, according to the Open Source Initiative, because it restricts the field of endeavour (offering the software as a service) ([OSI](https://opensource.org/blog/the-sspl-is-not-an-open-source-license))."]},{"heading":"Licences move: the drift of 2024 to 2026","paragraphs":["Choosing a licence once is not enough, because projects change them. Since SDK 4.0 in September 2025, tldraw “requires a license key to work in production”; without one it stops rendering after five seconds, and “internal products at companies is considered commercial use”; earlier versions were Apache-2.0 ([tldraw](https://tldraw.dev/sdk-features/license-key)). Zitadel moved from Apache-2.0 to AGPL-3.0 with version 3, effective 31 March 2025 ([Zitadel](https://zitadel.com/blog/apache-to-agpl)). Cal.com''s open repository is now Cal.diy, MIT-licensed but with teams, organisations, workflows and SSO removed ([Cal.diy](https://github.com/calcom/cal.diy)). NocoBase put version 3 onward under its own licence agreement, updated 16 November 2026 ([NocoBase](https://github.com/nocobase/nocobase)).","Industrial software moved the same way. EMQX adopted the Business Source License 1.1 from version 5.9.0, with free production use limited to a single node and excluding hosted or embedded offerings, and ThingsBoard followed from version 4.4.0; both convert to Apache-2.0 four years after each release ([EMQX licence](https://raw.githubusercontent.com/emqx/emqx/HEAD/LICENSE); [ThingsBoard licence](https://raw.githubusercontent.com/thingsboard/thingsboard/HEAD/LICENSE)). The United Manufacturing Hub went the other way, relicensing from AGPL-3.0 to Apache-2.0 and citing exactly this trend ([UMH](https://www.umh.app/insight/united-manufacturing-hub-relicensed-to-apache-2-0))."],"pullQuote":"The licence you checked at adoption is not the licence you will upgrade to."},{"heading":"How to hold each tier: a practical policy","paragraphs":["The policy below is our suggested practice, not a legal opinion. It is written for a company that builds or buys software around open-source components, and it is meant to make licence changes visible before they become a problem."],"bullets":["Keep a register: every dependency, its licence and the exact version you run. Recheck it at every upgrade, not once a year.","Embed only permissive or weak-copyleft components into your own code. Publish any changes you make to weak-copyleft libraries.","Run GPL and AGPL applications as separate, unmodified services that you call over their APIs. Decide in advance what you will do if a customer bans AGPL.","Treat source-available and fair-code tools as commercial software: read the licence, and buy the commercial licence before hosting or embedding them for anyone else.","Check the enterprise directory. In authentik, Fleet, Infisical, Rocket.Chat, Metabase, Windmill and Twenty, an ee/ or enterprise directory is under a separate licence, and the features a business needs (SSO, audit logs, fine-grained roles) are often in it.","Prefer foundation-governed or community-owned projects, such as Apache projects or Operaton, for anything that would be costly to replace."],"callout":{"title":"Where to go next","body":"Our back-office report lists the most credible open-source option for each department with its licence, and our D2C research does the same for commerce and marketing. If you are choosing components for a custom build, that choice is part of how we scope work with you."}}]'::jsonb,
  '["open source","licensing","software risk","research"]'::jsonb,
  '["saas-sprawl-statistics-2026","agentic-commerce-ucp-acp-explained","ai-support-agent-pricing-per-resolution"]'::jsonb,
  '[{"href":"/research/back-office-software-open-source-alternatives","label":"Back-office software map","note":"the most credible open-source option per function, with its licence"},{"href":"/research/d2c-marketing-tool-stack-agentic-commerce","label":"D2C tool stack research","note":"open source for commerce and marketing, and its gaps"},{"href":"/services","label":"Our services","note":"custom software built around the tools you choose"}]'::jsonb,
  '[{"question":"Can I use AGPL software in a commercial product?","answer":"Often, but with care. If you modify AGPL software and let users interact with it over a network, you must offer them the modified source. Running an unmodified AGPL application as a separate service beside your own code is the common way to use it. Some companies, Google among them, ban AGPL code entirely. Get legal advice for your situation."},{"question":"Is n8n open source?","answer":"Not under the OSI definition. n8n uses the Sustainable Use License, which allows use only for your own internal business purposes or for non-commercial or personal use, and its .ee files need an n8n Enterprise License. Embedding it in a product where customers connect their own credentials needs a paid agreement."},{"question":"Is the SSPL an open-source licence?","answer":"No. The Open Source Initiative said on 19 January 2021 that the SSPL is not an open source licence, because it restricts the field of endeavour (offering the software as a service), which the Open Source Definition does not allow."},{"question":"What is a Business Source License (BSL)?","answer":"A source-available licence that limits production use for a period and then converts to an open-source licence. Akaunting''s version caps production use at two users, one company or 1,000 invoices and converts each release to GPLv3 after four years; EMQX and ThingsBoard adopted BSL 1.1 in 2025 and 2026."},{"question":"How do I protect a product from licence changes upstream?","answer":"Record each dependency''s licence pinned to the version you use, recheck it at every upgrade, prefer foundation-governed or permissively licensed projects for anything you embed, and check whether the features you need sit in a separately licensed enterprise directory. This is a practical policy, not legal advice."}]'::jsonb,
  false,
  70,
  null,
  111,
  true
),
(
  'agentic-commerce-ucp-acp-explained',
  'Agentic Commerce Explained: UCP, ACP, AP2 and What Your Store Needs',
  'In-chat checkout stalled in 2026, but the standards it produced did not. What the Universal Commerce Protocol, the Agentic Commerce Protocol and AP2 ask of a brand''s catalogue, checkout and orders, and a readiness checklist.',
  'ChatGPT scaled back Instant Checkout, yet UCP, ACP and AP2 are now the rules AI shopping agents follow. What they ask your store to expose, and how to get ready.',
  'growth',
  10,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'layerStack',
  '{"primary":"agentic commerce","secondary":["universal commerce protocol","agentic commerce protocol","AP2 agent payments protocol","ChatGPT instant checkout","AI shopping agents for ecommerce"],"searchVolume":0,"difficulty":"medium","intent":"informational"}'::jsonb,
  '["In-chat checkout under-delivered: Walmart saw conversion three times lower inside the chatbot than when shoppers clicked out.","AI assistants are now a discovery channel fed by product feeds; the purchase completes on the merchant''s own checkout.","UCP, ACP and AP2 converge on the same requirements: a clean feed, live price and stock, checkout sessions, order webhooks, signed requests and scoped payment tokens.","In India the agent payment track is UPI, not card tokens.","The brand that owns catalogue, price, stock and orders in one place is the easiest one for an agent to buy from correctly."]'::jsonb,
  '[{"heading":"What happened to buying inside the chat","paragraphs":["The idea was simple: the shopper asks an assistant for a product, the assistant finds it and pays, and the shopper never visits a website. OpenAI and Stripe announced the Agentic Commerce Protocol in September 2025, with Etsy among the first merchants on ChatGPT Instant Checkout ([Stripe](https://stripe.com/blog/agentic-commerce-suite)). Shopify launched Agentic Storefronts on 10 December 2025, and Google announced the Universal Commerce Protocol at NRF on 11 January 2026 with Shopify, Etsy, Wayfair, Target and Walmart ([TechCrunch](https://www.techcrunch.com/2026/01/11/google-announces-a-new-protocol-to-facilitate-commerce-using-ai-agents/)).","By March 2026 it had stalled. OpenAI confirmed that “Instant Checkout is moving to Apps”, and on 24 March said merchants would use their own checkout while ChatGPT focuses on discovery ([Digital Commerce 360](https://www.digitalcommerce360.com/2026/03/06/openai-shifts-checkout-plans-agentic-commerce-strategy/)). Retailers explained why: Walmart''s Daniel Danker said conversion was three times lower for items sold inside the chatbot than for those that clicked out; Etsy did not see large volume; Instacart said only a very small share of orders start with agents; and retailers wanted live inventory, coupons, loyalty and store pickup without giving up the customer relationship ([Modern Retail](https://www.modernretail.co/technology/what-went-wrong-with-chatgpts-instant-checkout/)).","Shoppers do use assistants to look. In Forrester''s December 2025 survey, 23% of Gen X, 32% of Millennials and 35% of Gen Z had used ChatGPT to search for products in the past month, but completing a purchase inside an answer engine was the least-adopted use ([Forrester](https://www.forrester.com/blogs/what-it-means-that-the-leader-in-agentic-commerce-just-pulled-back/)). The practical conclusion: AI assistants are a discovery channel, and the checkout stays with the brand."],"pullQuote":"Assistants became the place to discover products. The checkout stayed with the brand."},{"heading":"ACP, UCP and AP2 in plain terms","paragraphs":["Three open standards came out of this period, and they overlap more than their names suggest."],"bullets":["The Agentic Commerce Protocol (ACP), from OpenAI and Stripe, is Apache-2.0; its repository was last pushed on 18 July 2026 ([ACP](https://github.com/agentic-commerce-protocol/agentic-commerce-protocol)). It defines how an agent creates, updates, retrieves and completes a checkout session with a merchant.","The Universal Commerce Protocol (UCP), from Google with Shopify and other retailers, is also Apache-2.0, with its latest release tagged v2026-08-25 ([UCP](https://github.com/Universal-Commerce-Protocol/ucp)). Its capabilities are Catalog, Cart, Checkout, Identity Linking (OAuth 2.0) and Order (confirmation, fulfilment, webhooks, returns), over REST or JSON-RPC, with AP2, A2A and MCP built in. Businesses remain merchant of record ([ucp.dev](https://ucp.dev/)).","The Agent Payments Protocol (AP2) is Apache-2.0, at v0.2.0 since 28 April 2026 ([AP2](https://github.com/google-agentic-commerce/AP2)). UCP uses it for payment mandates backed by cryptographic proof of user consent.","Shopify serves UCP over MCP on every store at /api/ucp/mcp, with Catalog, Cart, Checkout, Ask (policies and FAQs) and Order servers; the older Storefront MCP tools were removed ([Shopify](https://shopify.dev/docs/apps/build/storefront-mcp))."],"callout":{"title":"Who has signed up","body":"UCP''s site lists Flipkart, Visa, Mastercard, PayPal, Stripe, Adyen, Salesforce, SAP, Zalando and Shopee as endorsers. Visa''s Intelligent Commerce Connect, in pilot, supports ACP, UCP and two further agent protocols. Whether Flipkart, Meesho or ONDC expose agent-facing catalogues today was not verified."}},{"heading":"The product feed: the fields an assistant reads","paragraphs":["Discovery runs on feeds. OpenAI''s commerce documentation lists the required fields for a ChatGPT product feed: item_id, title, description, url, image_url, brand, seller_name, availability, price with an ISO currency code, target_countries and store_country. Each variant gets its own row, tied together by a shared group_id. Feeds are accepted as JSONL, CSV or TSV by upload, HTTPS URL or SFTP once the business is claimed and verified, and the feed currently represents the US, Canada and Mexico ([OpenAI](https://developers.openai.com/commerce/llms-full.txt)).","None of these fields is exotic, but each one is a place where a brand''s systems tend to disagree. The title in the PIM differs from the title on the storefront; availability is updated hourly in the warehouse system and daily in the feed; the price on the marketplace includes a promotion the feed does not know about. An assistant that reads a stale price will quote it to the shopper, and the shopper will hold the brand to it.","Medusa''s agentic commerce guide refreshes the product feed every 15 minutes ([Medusa](https://docs.medusajs.com/resources/how-to-tutorials/tutorials/agentic-commerce)). If your stock moves faster than that, the feed needs to come from the same record the checkout reads, not from a nightly export."]},{"heading":"Checkout sessions, signed requests and scoped payment tokens","paragraphs":["Medusa''s implementation of ACP shows the shape of the checkout side: endpoints to create a checkout session, update and retrieve it by id, and complete it; a Bearer key plus an HMAC signature on requests; and signed order webhooks. The guide notes that “ChatGPT currently supports only Stripe as a payment provider” ([Medusa](https://docs.medusajs.com/resources/how-to-tutorials/tutorials/agentic-commerce)).","Payment no longer arrives as a card number. Stripe''s Agentic Commerce Suite issues Shared Payment Tokens scoped to a seller, a time and an amount ([Stripe](https://stripe.com/blog/agentic-commerce-suite)), and ChatGPT''s own checkout uses a network token per transaction. On Shopify, every agent request must carry an agent profile, each cart update replaces the whole cart, checkout requests must be authenticated or signed, and an agent using Shop MCP completes checkout only after the buyer confirms the total and payment method ([Shopify agents docs](https://shopify.dev/docs/agents))."],"callout":{"title":"Why this matters for operations, not just IT","body":"Every agent order still has to be picked, packed, invoiced, shipped and possibly returned. UCP''s Order capability includes fulfilment and returns webhooks for that reason. An order that arrives with the AI channel recorded (Shopify records it in the admin) is also the only way to measure whether the channel is worth the effort."}},{"heading":"India: UPI, not card tokens","paragraphs":["India is on its own payment track. On 9 October 2025 Razorpay, NPCI and OpenAI launched an “Agentic Payments” pilot on ChatGPT built on UPI Reserve Pay and UPI Circle, with BigBasket as a first merchant and Axis Bank and Airtel Payments Bank as banking partners ([Razorpay](https://razorpay.com/newsroom/razorpay-npci-and-openai-come-together-to-launch-agentic-payments-ushering-in-ai-driven-commerce-at-national-scale/)). Card networks have only demonstrated agent payments here: Mastercard completed an Agent Pay purchase at the India AI Impact Summit in February 2026 in a “controlled environment”, with no partners or launch date given ([PaymentsJournal](https://www.paymentsjournal.com/mastercard-advances-agentic-ai-commerce-in-india/)).","No 2026 status update on the UPI pilot was found, and no independent figure exists for the share of Indian e-commerce orders that start in an AI assistant. In our view an Indian brand should plan for UPI mandates rather than card tokens for agent purchases, and should not rebuild its checkout around a channel whose volume nobody can yet measure."]},{"heading":"A readiness checklist for a brand","paragraphs":["This checklist is ours. It follows the requirements common to ACP, UCP and Shopify''s implementation, ordered so the early steps pay off even if agent traffic stays small, because the same fixes help search engines and human shoppers."],"bullets":["One product record: SKU, title, description, images, brand, variants, price with currency and availability held in one place that the storefront, the marketplaces and the feed all read.","Stable ids and GTIN or MPN where you have them, one row per variant with a shared group id.","Live price and stock exposed through a catalogue search or lookup, not only a nightly file.","A policy and FAQ answer source (shipping, returns, warranty) that an agent can quote accurately.","Checkout sessions you control, able to accept a scoped payment token, with signed requests and order webhooks.","Order status, fulfilment and returns events that an agent can read back to the shopper.","Identity linking, so loyalty prices and saved addresses apply when a known customer arrives through an agent.","The channel recorded on every order, so you can see what agent traffic is worth."],"callout":{"title":"Where to start","body":"If your product record is copied across a storefront, an order-management tool, marketplaces and a spreadsheet, fix that first. Our D2C research report shows how many tools typically touch it, and our post on catalogue conversion covers what human shoppers need from the same data."}}]'::jsonb,
  '["agentic commerce","ecommerce","ai agents","research"]'::jsonb,
  '["ai-support-agent-pricing-per-resolution","d2c-catalog-conversion","generative-engine-optimization-for-smes"]'::jsonb,
  '[{"href":"/research/d2c-marketing-tool-stack-agentic-commerce","label":"D2C tool stack research","note":"the full report on the brand stack, MCP and agentic commerce"},{"href":"/blogs/d2c-catalog-conversion","label":"D2C catalogue conversion","note":"fixing the catalogue humans and agents both read"},{"href":"/contact","label":"Talk to us","note":"a free first conversation about your stack"}]'::jsonb,
  '[{"question":"What is agentic commerce?","answer":"Shopping where an AI assistant searches products, builds a cart and sometimes pays for the shopper. In 2026 it settled into discovery and referral: assistants read brands'' product feeds and send shoppers to the merchant''s own checkout."},{"question":"What is the difference between UCP and ACP?","answer":"The Agentic Commerce Protocol, from OpenAI and Stripe, centres on checkout sessions with signed requests and order webhooks. The Universal Commerce Protocol, announced by Google with Shopify and others, covers catalogue, cart, checkout, identity linking and orders, and builds in AP2 for payment mandates. Both are Apache-2.0."},{"question":"Is ChatGPT Instant Checkout still available?","answer":"It was scaled back. In March 2026 OpenAI confirmed that Instant Checkout was moving to apps and that merchants would use their own checkout while ChatGPT focuses on discovery. Shopify says ChatGPT purchases now complete on the merchant''s own checkout in an in-app browser."},{"question":"How will AI agents pay in India?","answer":"The live pilot runs on UPI. Razorpay, NPCI and OpenAI launched Agentic Payments on ChatGPT in October 2025 on UPI Reserve Pay and UPI Circle, with BigBasket as an early merchant. Mastercard showed an agent card payment in India only as a controlled demonstration in February 2026."},{"question":"Should a brand block AI shopping agents?","answer":"It is harder than it looked. A US district judge blocked Perplexity''s Comet agent from shopping on Amazon in March 2026, but an appeals court later vacated the injunction, reasoning that the user who directs the assistant is the one accessing the site. Most brands are better served by giving agents an official, controlled way in."}]'::jsonb,
  false,
  76,
  null,
  112,
  true
),
(
  'ai-support-agent-pricing-per-resolution',
  'AI Support Agent Pricing 2026: Fin, Zendesk, Agentforce Compared',
  'Support is the one place AI agents work end to end at scale, and they are priced per result. What Intercom, Zendesk, Salesforce, Freshdesk, Gorgias, Meta and Interakt charge, what each one counts as a “resolution”, and a worked cost example.',
  'AI support agents cost $0.85 to $2.00 per resolution in 2026, but every vendor defines a resolution differently. Prices compared, Klarna''s reversal, and what to measure.',
  'automation',
  10,
  '2026-11-23',
  null,
  '{"name":"Savin Group Research","role":"Research desk, Savin Group","bio":"Reads vendor documentation, release notes, standards and public benchmarks so manufacturers and brands can see what software and AI agents actually do, with every figure linked to its source."}'::jsonb,
  'whatsappFlow',
  '{"primary":"AI customer support agent pricing","secondary":["Intercom Fin price per resolution","Zendesk AI agent pricing","Agentforce pricing","outcome based pricing AI","WhatsApp AI agent cost India"],"searchVolume":0,"difficulty":"medium","intent":"commercial"}'::jsonb,
  '["Support agents are the clearest case of outcome pricing: roughly $0.85 to $2.00 per resolved conversation in 2026.","“Resolution” and “outcome” are defined by the vendor that bills for them, so headline rates are not comparable.","Reported resolution rates of 70% or more are vendor figures; none has been independently audited.","Klarna''s reversal shows the cost of optimising for deflection over quality.","Compare vendors on your own traffic: billable units, hand-off quality, reopen rate and cost per truly resolved issue."]'::jsonb,
  '[{"heading":"The price list, side by side","paragraphs":["Customer support is the one function where AI agents work end to end at scale and are priced by result. These are the published prices as read on 22 November 2026."],"bullets":["Intercom Fin AI Agent: $0.99 per outcome, on any Intercom plan or beside another helpdesk; Copilot for human agents $29 per agent a month ([Intercom](https://www.intercom.com/pricing)).","Zendesk: $2.00 per automated resolution pay-as-you-go, lower when committed, with 5 to 10 included per agent a month; Copilot $50 per agent ([Zendesk](https://www.zendesk.com/pricing/)).","Salesforce Agentforce: $2 per conversation, or Flex Credits at $500 per 100,000 with 20 credits per action, which works out at 10 US cents an action ([Agentforce](https://www.salesforce.com/agentforce/pricing/)).","Freshdesk Freddy AI Agent: 500 sessions included once, then $49 per 100 sessions; a session is one end-user interaction and email sessions last 72 hours ([Freshdesk](https://www.freshworks.com/freshdesk/pricing/)).","Gorgias AI Agent: $1.00, $0.90 or $0.85 per automated interaction depending on plan, as shown on its pricing page in a search summary ([Gorgias](https://gorgias.com/pricing)).","Chatwoot Captain: 300 to 800 credits a month in paid plans, $20 per extra 1,000 ([Chatwoot](https://www.chatwoot.com/pricing)).","Meta Business Agent on WhatsApp: $2.00 per million tokens, about 4 to 5 US cents a message, since 1 July 2026 ([Meta](https://developers.facebook.com/docs/whatsapp/pricing)).","Interakt WhatsApp AI Agents: ₹2,499 a month with 100 AI messages, then ₹0.50 per AI message ([Interakt](https://www.interakt.shop/pricing/))."]},{"heading":"What counts as a resolution depends on who is billing","paragraphs":["The unit is where the real price hides. Zendesk bills only requests “the AI agent resolves without escalation to a human agent”. Gorgias counts an interaction as automated when no human was needed within 72 hours, and a fully automated ticket can also count as a ticket. Freshdesk bills sessions, not outcomes. Salesforce offers both a per-conversation price and per-action credits.","Intercom made the most consequential change. In March 2026 it moved its billing unit from “resolution” to “outcome”, and an outcome also counts configured hand-offs to a person ([Intercom](https://www.intercom.com/blog/fin-ai-agent-resolution-rates)). That is a defensible product decision, since a clean hand-off with the context attached is useful work. But it means Intercom''s $0.99 and Zendesk''s $2.00 are not prices for the same thing.","The newer enterprise vendors are less transparent still. Sierra prices by volume or by outcome, blended per client, and Decagon more commonly per conversation, with a higher rate per resolution as the alternative ([Sacra](https://sacra.com/c/decagon/)). Neither publishes a list price. And per-result pricing sits on top of the seats your human agents still need: Zendesk''s Suite Team plan is $55 per agent a month on annual billing, and Intercom''s seats run from $29 list to $132 a month before any AI is added ([Zendesk](https://www.zendesk.com/pricing/); [Intercom](https://www.intercom.com/pricing)). A vendor comparison that looks only at the AI line understates the bill."],"callout":{"title":"Read the definition before the price","body":"Before comparing vendors, write down for each one what triggers a charge: a conversation, a session, an action, a resolution with no human, or an outcome that may include a hand-off. Then price your own last month of tickets under each definition."}},{"heading":"Reported resolution rates, and how far to trust them","paragraphs":["Intercom reports a 76% average resolution rate for Fin across more than 12,000 teams, in a chart labelled June 2026; a search summary quoted 67% for March 2026 ([Intercom](https://www.intercom.com/blog/fin-ai-agent-resolution-rates)). Analyst firm Sacra estimates about 70% containment for Sierra''s enterprise clients and $400M ARR in October 2026, after Sierra was valued at $15.8 billion in May 2026 ([Sacra](https://www.sacra.com/c/sierra)). For Decagon, valued at $4.5 billion in January 2026, one client reported 90% resolution without a person and another cut its support team by 80% ([Sacra](https://sacra.com/c/decagon/)).","These are vendor-reported figures or analyst estimates, not audits, and no independent audit of any support agent''s resolution rate was found in our research. Rates also depend heavily on the mix of questions: a brand whose tickets are mostly “where is my order” will see higher numbers than one handling warranty claims."]},{"heading":"The Klarna lesson","paragraphs":["Klarna made the most prominent bet. In February 2024 it said its AI assistant handled about two-thirds of chats, 2.3 million in the first month, and did the work of 700 agents. In May 2025 its CEO said that “cost unfortunately seems to have been a too predominant evaluation factor”, that this lowered quality, and that customers would always be able to reach a person; Klarna began recruiting human agents again ([Customer Experience Dive](https://www.customerexperiencedive.com/news/klarna-reinvests-human-talent-ai-customer-service-buy-now-pay-later/747586/)).","The pattern repeats across functions. The cases that hold up keep a person approving or supervising; in a December 2025 survey of martech leaders, 80.6% kept their AI agents in assist-only, human-in-the-loop mode ([chiefmartec, reported](https://newsletter.chiefmartec.com/p/here-s-your-ungated-copy-of-the-state-of-martech-2026-report)). Our [D2C research report](/research/d2c-marketing-tool-stack-agentic-commerce) shows the same pattern in AI sales outreach and in-chat checkout."],"pullQuote":"Deflection is easy to measure and easy to overvalue. A customer who gives up is also a deflected ticket."},{"heading":"An illustrative cost comparison","paragraphs":["This worked example is ours and uses made-up volumes, not any customer''s data. Assume a brand receives 10,000 support conversations a month, the AI fully resolves 6,000 of them, and each conversation averages six AI messages. Applying only the published AI-agent prices above, before seats, platform fees and taxes:"],"bullets":["Intercom Fin: 6,000 outcomes at $0.99 is about $5,940, more if configured hand-offs also count as outcomes.","Zendesk pay-as-you-go: 6,000 resolutions at $2.00 is about $12,000, less with a commitment.","Gorgias: 6,000 automated interactions at $0.85 to $1.00 is about $5,100 to $6,000.","Salesforce Agentforce: at $2 per conversation for all 10,000 conversations, about $20,000; on Flex Credits at three actions per conversation, about $3,000.","Freshdesk: 10,000 sessions at $49 per 100 is about $4,900 a month once the one-time 500 are used.","Meta Business Agent: 60,000 messages at 4 to 5 US cents is about $2,400 to $3,000, plus any provider fee.","Interakt: ₹2,499 plus 59,900 AI messages at ₹0.50 is about ₹32,449 a month."],"callout":{"title":"What the example does not show","body":"The spread is wide because the units differ, not only the prices. The cheapest line is not the cheapest system if its resolutions get reopened, if its hand-offs lose context, or if it runs on a channel your customers do not use. Seats for human agents, Copilot add-ons and the helpdesk itself are extra in every case."}},{"heading":"What to measure before you sign","paragraphs":["The questions below are our checklist for a support-agent trial. They are designed to make vendors comparable on your own traffic rather than on their headline rate."],"bullets":["Billable unit: exactly what triggers a charge, and whether hand-offs, reopened tickets or abandoned chats are billed.","Resolution quality: the share of “resolved” conversations that come back within seven days.","Hand-off quality: whether the human agent receives the full conversation, the order and the customer record, or starts from zero.","Actions: which tools the agent may call (refunds, address changes, cancellations) and which need a person''s approval first.","Data access: which customer and order fields the agent can read, and where those conversations are processed.","Channel: whether the agent works where your customers write, which in India is often WhatsApp.","Cost per truly resolved issue: total monthly cost divided by resolutions that stayed resolved."],"callout":{"title":"Agents that act on orders need the order","body":"A support agent that can only answer questions is a FAQ with better grammar. One that can check an order, raise a return or correct an address needs governed access to those records, with a person approving the consequential steps. That is the design behind our agentic ERP and CRM work."}}]'::jsonb,
  '["ai agents","customer support","pricing","research"]'::jsonb,
  '["agentic-commerce-ucp-acp-explained","whatsapp-as-crm","saas-sprawl-statistics-2026"]'::jsonb,
  '[{"href":"/research/d2c-marketing-tool-stack-agentic-commerce","label":"D2C tool stack research","note":"support, sales, ads and creative agents with their numbers"},{"href":"/agentic-erp-crm","label":"Agentic ERP & CRM","note":"agents with approved tools and human approval"},{"href":"/blogs/whatsapp-as-crm","label":"WhatsApp as CRM","note":"the channel most Indian support already runs on"}]'::jsonb,
  '[{"question":"How much does an AI customer support agent cost per resolution?","answer":"Published prices in November 2026 range from about $0.85 to $2.00: Intercom Fin $0.99 per outcome, Gorgias $0.85 to $1.00 per automated interaction (reported), Zendesk $2.00 per automated resolution pay-as-you-go, and Salesforce Agentforce $2 per conversation or Flex Credits at about 10 US cents an action."},{"question":"What counts as a resolution for AI support billing?","answer":"Each vendor decides. Zendesk bills requests the AI resolves without escalation to a human. Gorgias counts an interaction as automated when no human was needed within 72 hours. Intercom changed its billing unit from “resolution” to “outcome” in March 2026, which also counts configured hand-offs."},{"question":"What resolution rate can an AI support agent reach?","answer":"Vendors report 70% or more. Intercom shows a 76% average resolution rate for Fin in a chart labelled June 2026, and analyst estimates put Sierra''s enterprise containment at about 70%. None of these figures has been independently audited, and they use different definitions."},{"question":"Why did Klarna bring back human support agents?","answer":"In May 2025 Klarna''s CEO said cost had been too predominant an evaluation factor and that this lowered quality, and that customers would always be able to reach a person. Klarna had earlier said its assistant handled about two-thirds of chats, the work of 700 agents."},{"question":"How much does a WhatsApp AI agent cost in India?","answer":"Meta''s own Business Agent message category costs $2.00 per million tokens, about 4 to 5 US cents a message, since 1 July 2026. Providers price on top: Interakt''s WhatsApp AI Agents cost ₹2,499 a month with 100 AI messages included, then ₹0.50 per AI message."}]'::jsonb,
  false,
